window.ECHO_XW6 = [{"id":"med-de-1","cat":"med","lang":"de","level":3,"title":"Herz, Gefäße & Blut I","w":18,"h":20,"x":11,"entries":[{"d":"a","r":0,"c":2,"a":"LYMPHOEDEM","q":"Chronische Schwellung durch gestörten Lymphabfluss: primär (angeborene Fehlanlage) oder – häufiger – sekundär nach …","n":1,"info":"Lymphödem: Schmerzlose, anfangs weiche, später derbe Schwellung eines Arms oder Beins, Schweregefühl; Finger bzw. Zehen mitbetroffen."},{"d":"a","r":2,"c":3,"a":"VORHOFFLIMMERN","q":"Häufigste anhaltende Herzrhythmusstörung: ungeordnete, sehr schnelle Erregung der Vorhöfe mit unregelmäßiger …","n":3,"info":"Vorhofflimmern: Unregelmäßiger, oft schneller Puls (Arrhythmia absoluta), Herzstolpern, Leistungsknick; häufig auch symptomlos"},{"d":"a","r":4,"c":4,"a":"ATHEROSKLEROSE","q":"Chronisch-entzündliche Erkrankung der … mit Einlagerung von Lipiden (LDL), Plaquebildung, Verhärtung und …","n":5,"info":"Atherosklerose (Arteriosklerose): Lange stumm; Beschwerden erst durch Organfolgen: Angina pectoris, Claudicatio, TIA oder Schlaganfall"},{"d":"a","r":8,"c":1,"a":"RAYNAUDSYNDROM","q":"Anfallsartige Gefäßkrämpfe der Finger (seltener Zehen) durch Kälte oder Stress","n":8,"info":"Raynaud-Syndrom: Dreiphasiger Farbwechsel der Finger: weiß (Ischämie) → blau (Zyanose) → rot (Hyperämie); Taubheit, Schmerz"},{"d":"a","r":10,"c":0,"a":"AORTA","q":"Aus welchem Gefäßabschnitt gehen Truncus brachiocephalicus und linke A. subclavia ab?","n":9,"info":"Aorta (Aortenbogen): Hauptschlagader; aus dem Bogen entspringen Truncus brachiocephalicus, A. carotis communis sinistra und A. subclavia sinistra."},{"d":"a","r":11,"c":6,"a":"AORTENKLAPPE","q":"Welche Klappe öffnet sich, damit Blut aus der linken Kammer in den Körperkreislauf gelangt?","n":11,"info":"Aortenklappe: Taschenklappe mit drei Taschen am Ausgang der linken Kammer; aus den Sinus aortae dahinter entspringen die Koronararterien."},{"d":"d","r":0,"c":4,"a":"MYOKARDINFARKT","q":"Untergang von Herzmuskelgewebe durch akuten Verschluss einer Koronararterie, meist durch Ruptur eines …","n":2,"info":"Myokardinfarkt (Herzinfarkt, STEMI/NSTEMI): Starker, anhaltender Brustschmerz (>20 min), nitroresistent, Vernichtungsgefühl, Kaltschweiß, Übelkeit; bei Frauen/Diabetikern oft atypisch"},{"d":"d","r":3,"c":17,"a":"LEUKOZYTEN","q":"Welche kernhaltigen Blutzellen dienen der Abwehr?","n":4,"info":"Leukozyten: Weiße Blutkörperchen der Abwehr: Granulozyten, Monozyten und Lymphozyten; normal ca. 4.000–10.000 pro µl."},{"d":"d","r":4,"c":10,"a":"SPLENOMEGALIE","q":"Vergrößerung der Milz","n":6,"info":"Splenomegalie (Milzvergrößerung): Druck- oder Völlegefühl im linken Oberbauch, frühe Sättigung; oft Zufallsbefund; Zeichen der Grunderkrankung"},{"d":"d","r":6,"c":1,"a":"VORHOFFLATTERN","q":"Kreisende Erregung (Makro-Reentry) im rechten …, typischerweise um den Trikuspidalklappenring, mit …","n":7,"info":"Vorhofflattern: Herzrasen, regelmäßig schnell (oft um 150/min), Schwindel, Leistungsabfall"},{"d":"d","r":10,"c":14,"a":"VARIKOSE","q":"Erweiterte, geschlängelte oberflächliche Beinvenen durch Klappenschwäche und Wandschwäche; meist primär (familiär, …","n":10,"info":"Varikose (Krampfadern): Sichtbare, geschlängelte Venen, abendliches Schwere- und Spannungsgefühl, Knöchelschwellung, nächtliche Wadenkrämpfe"}]},{"id":"med-de-2","cat":"med","lang":"de","level":3,"title":"Herz, Gefäße & Blut II","w":15,"h":19,"x":11,"entries":[{"d":"a","r":0,"c":6,"a":"MILZHILUS","q":"Wo treten die Milzgefäße ein und aus?","n":2,"info":"Milzhilus: Liegt an der Facies visceralis; Ein- und Austritt von A. und V. lienalis, in Nachbarschaft zum Pankreasschwanz."},{"d":"a","r":2,"c":1,"a":"BLUTPLASMA","q":"Wie heißt der zellfreie flüssige Anteil des Blutes, der noch Gerinnungsfaktoren enthält?","n":3,"info":"Blutplasma: Flüssiger Anteil (ca. 55 %) aus Wasser, Elektrolyten, Proteinen (v. a. Albumin), Nährstoffen und Hormonen; ohne Gerinnungsfaktoren heißt es Serum."},{"d":"a","r":7,"c":0,"a":"KAROTISSTENOSE","q":"Atherosklerotische Verengung der Halsschlagader, meist an der Gabelung am Abgang der A. carotis interna","n":9,"info":"Karotisstenose: Oft symptomlos; symptomatisch: TIA oder Schlaganfall, Amaurosis fugax (flüchtige einseitige Erblindung)"},{"d":"d","r":0,"c":3,"a":"MGUS","q":"Häufige, symptomlose Vorstufe von Plasmazell- oder B-Zell-Neoplasien: kleines … Paraprotein ohne Organschäden","n":1,"info":"MGUS (monoklonale Gammopathie unklarer Signifikanz): Keine Beschwerden; Zufallsbefund bei Abklärung einer erhöhten BSG oder Eiweißelektrophorese."},{"d":"d","r":0,"c":6,"a":"MILZKAPSEL","q":"Welche dünne Hülle reißt beim linksseitigen Bauchtrauma und führt zur inneren Blutung?","n":2,"info":"Milzkapsel: Dünne bindegewebige Kapsel mit Trabekeln; bei Trauma im linken Oberbauch droht eine Milzruptur mit starker Blutung."},{"d":"d","r":2,"c":12,"a":"THYMUS","q":"In welchem Organ reifen die T-Lymphozyten?","n":4,"info":"Thymus: Liegt im vorderen oberen Mediastinum; Ort der T-Zell-Reifung, bildet sich nach der Pubertät zum Fettkörper zurück."},{"d":"d","r":3,"c":0,"a":"PERIKARDITIS","q":"Entzündung des …, meist viral oder idiopathisch; außerdem nach Infarkt oder Herz-OP, bei Urämie, …","n":5,"info":"Perikarditis (Herzbeutelentzündung): Scharfer, atemabhängiger Brustschmerz, besser im Sitzen mit Vorbeugen, schlechter im Liegen; Perikardreiben"},{"d":"d","r":4,"c":2,"a":"MITRALKLAPPE","q":"Welche Herzklappe hat nur zwei Segel?","n":6,"info":"Mitralklappe: Segelklappe mit zwei Segeln (Bikuspidalklappe) zwischen linkem Vorhof und linker Kammer; Auskultation an der Herzspitze."},{"d":"d","r":4,"c":8,"a":"AORTENBOGEN","q":"Welcher Gefäßabschnitt krümmt sich über den linken Hauptbronchus nach hinten?","n":7,"info":"Aortenbogen (Arcus aortae): Gibt Truncus brachiocephalicus, A. carotis communis sinistra und A. subclavia sinistra ab; in seiner Wand liegen Barorezeptoren."},{"d":"d","r":5,"c":10,"a":"LUNGENVENEN","q":"Welche Gefäße führen sauerstoffreiches Blut zum Herzen?","n":8,"info":"Lungenvenen: Meist vier Venen (je zwei pro Seite), die sauerstoffreiches Blut aus der Lunge in den linken Vorhof führen."},{"d":"d","r":7,"c":4,"a":"THROMBOZYTEN","q":"Welche Zellfragmente bilden bei Verletzungen den ersten Pfropf?","n":10,"info":"Thrombozyten: Kernlose Zellfragmente aus Megakaryozyten; bilden den Plättchenpfropf der primären Blutstillung und leben ca. 7–10 Tage."}]},{"id":"med-de-3","cat":"med","lang":"de","level":3,"title":"Herz, Gefäße & Blut III","w":17,"h":19,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"LYMPHKNOTEN","q":"Welche Filterstationen sind in die Lymphbahnen eingeschaltet?","n":1,"info":"Lymphknoten: Bohnenförmige Filterstationen (meist unter 1 cm) entlang der Lymphbahnen; mehrere zuführende Gefäße, ein abführendes am Hilus."},{"d":"a","r":2,"c":2,"a":"PULMONALKLAPPE","q":"Welche Taschenklappe verhindert den Rückstrom aus dem Lungenarterienstamm in die rechte Kammer?","n":3,"info":"Pulmonalklappe: Taschenklappe am Ausgang der rechten Kammer; schließt zu Beginn der Diastole und bildet mit der Aortenklappe den 2. Herzton."},{"d":"a","r":5,"c":4,"a":"ERYTHROZYTEN","q":"Welche kernlosen Blutzellen transportieren Sauerstoff?","n":4,"info":"Erythrozyten: Kernlose bikonkave Scheiben (ca. 7,5 µm) voller Hämoglobin; transportieren O₂ und CO₂ und leben ca. 120 Tage."},{"d":"a","r":7,"c":4,"a":"MEGAKARYOZYT","q":"Welche Riesenzelle des Knochenmarks schnürt Blutplättchen ab?","n":5,"info":"Megakaryozyt: Riesige polyploide Knochenmarkzelle; schnürt Tausende Thrombozyten ab, gesteuert durch Thrombopoetin aus der Leber."},{"d":"a","r":11,"c":5,"a":"MARGINALZONE","q":"Welche Grenzzone der Milz fängt bekapselte Bakterien aus dem Blut ab?","n":8,"info":"Marginalzone: Grenze zwischen weißer und roter Pulpa mit speziellen B-Zellen und Makrophagen; fängt Antigene aus dem Blut ab, v. a. bekapselte Bakterien."},{"d":"a","r":14,"c":6,"a":"TONSILLEN","q":"Welche lymphatischen Organe überwachen ringförmig den Eingang von Atem- und Speiseweg?","n":10,"info":"Tonsillen (Waldeyer-Rachenring): Gaumen-, Rachen-, Zungen- und Tubenmandeln überwachen den Eingang von Atem- und Speiseweg."},{"d":"d","r":0,"c":5,"a":"KAMMERSEPTUM","q":"Welche Struktur trennt die beiden Ventrikel voneinander?","n":2,"info":"Kammerseptum: Trennwand zwischen den Kammern, größtenteils muskulär mit kleinem membranösem Anteil oben; in ihr verlaufen His-Bündel und Tawara-Schenkel."},{"d":"d","r":2,"c":2,"a":"PEYERPLAQUES","q":"Welche Lymphfollikelansammlungen im Ileum überwachen den Darminhalt?","n":3,"info":"Peyer-Plaques: Ansammlungen von Lymphfollikeln v. a. im Ileum; darüberliegende M-Zellen schleusen Antigene aus dem Darmlumen ein."},{"d":"d","r":9,"c":7,"a":"PARAKORTEX","q":"Welche Zone des Lymphknotens ist T-Zell-reich und enthält hochendotheliale Venolen?","n":6,"info":"Parakortex: T-Zell-Zone zwischen Rinde und Mark; über hochendotheliale Venolen (HEV) wandern Lymphozyten aus dem Blut ein."},{"d":"d","r":10,"c":9,"a":"MILZSINUS","q":"Durch welche schlitzförmigen Gefäßwände müssen sich Erythrozyten in der roten Pulpa zwängen?","n":7,"info":"Milzsinus: Weite Venensinus mit schlitzförmigen Wandlücken (Stabzellen); Erythrozyten müssen sich hindurchzwängen, starre Zellen bleiben hängen."},{"d":"d","r":11,"c":11,"a":"AVBLOCK","q":"Verzögerte oder unterbrochene Erregungsleitung von den Vorhöfen auf die Kammern im AV-Knoten oder His-Bündel","n":9,"info":"AV-Block: Grad I meist symptomlos; höhergradig: Schwindel, Bradykardie, Synkopen (Adams-Stokes-Anfall)"}]},{"id":"med-de-4","cat":"med","lang":"de","level":4,"title":"Herz, Gefäße & Blut IV","w":14,"h":18,"x":11,"entries":[{"d":"a","r":0,"c":3,"a":"HAEMOGLOBIN","q":"Welches eisenhaltige Protein der Erythrozyten bindet Sauerstoff?","n":1,"info":"Hämoglobin: Tetramer aus zwei α- und zwei β-Ketten (HbA) mit je einem Häm (Fe²⁺), das O₂ bindet; 2,3-BPG senkt seine O₂-Affinität."},{"d":"a","r":2,"c":3,"a":"PALS","q":"Welche T-Zell-Zone der Milz umhüllt die Zentralarterien?","n":4,"info":"PALS (periarterioläre Lymphozytenscheide): T-Zell-Zone, die die Zentralarterien der weißen Pulpa manschettenartig umhüllt."},{"d":"a","r":4,"c":0,"a":"LYMPHKAPILLARE","q":"Welche blind beginnenden Gefäße nehmen überschüssige Gewebeflüssigkeit auf?","n":8,"info":"Lymphkapillare: Blind beginnende, sehr durchlässige Gefäße im Gewebe; nehmen Flüssigkeit, Proteine und Zellen auf, die nicht in die Venen zurückkehren."},{"d":"a","r":13,"c":3,"a":"ENDOTHEL","q":"Welche Zellschicht kleidet die Gefäße innen aus und bildet Stickstoffmonoxid?","n":11,"info":"Endothel: Einschichtiges Plattenepithel, das alle Gefäße auskleidet; bildet NO (gefäßerweiternd) und regelt Gerinnung und Durchlässigkeit."},{"d":"d","r":0,"c":4,"a":"ANAPHYLAXIE","q":"Akute, lebensbedrohliche systemische Überempfindlichkeitsreaktion, meist IgE-vermittelt mit Mastzellaktivierung","n":2,"info":"Anaphylaxie: Innerhalb von Minuten: Nesselsucht/Flush, Schwellungen, Atemnot/Stridor, Blutdruckabfall, Erbrechen; bis Kreislaufstillstand."},{"d":"d","r":2,"c":0,"a":"MILZFOLLIKEL","q":"Wo entstehen in der Milz nach Antigenkontakt antikörperbildende Zellen?","n":3,"info":"Milzfollikel (Malpighi-Körperchen): B-Zell-Zonen mit Keimzentren, in denen nach Antigenkontakt Plasma- und Gedächtniszellen entstehen."},{"d":"d","r":2,"c":9,"a":"MILZRUPTUR","q":"Einriss der Milz, meist durch stumpfes Bauchtrauma (Verkehrsunfall, Sturz, Rippenbrüche links); seltener spontan bei …","n":5,"info":"Milzruptur: Schmerz im linken Oberbauch mit Ausstrahlung in die linke Schulter (Kehr-Zeichen), Zeichen des hämorrhagischen Schocks"},{"d":"d","r":3,"c":11,"a":"KAPILLARE","q":"In welchen Gefäßen findet der Stoffaustausch mit dem Gewebe statt?","n":6,"info":"Kapillare: Wand nur aus Endothel, Basalmembran und Perizyten; Typen: kontinuierlich, gefenstert, diskontinuierlich (Sinusoide)."},{"d":"d","r":3,"c":13,"a":"RETIKULOZYT","q":"Welche junge rote Blutzelle zeigt die aktuelle Blutbildungsaktivität an?","n":7,"info":"Retikulozyt: Junger Erythrozyt mit RNA-Resten; sein Anteil im Blut zeigt die aktuelle Erythropoese-Leistung des Knochenmarks."},{"d":"d","r":4,"c":6,"a":"ARBEITSMYOKARD","q":"Welches Gewebe leistet die eigentliche Pumparbeit des Herzens?","n":9,"info":"Arbeitsmyokard (Kardiomyozyten, Glanzstreifen): Quergestreifte, verzweigte Zellen mit zentralem Kern; Glanzstreifen mit Gap Junctions koppeln sie elektrisch zu einem funktionellen Synzytium."},{"d":"d","r":12,"c":3,"a":"SEPSIS","q":"Lebensbedrohliche Organfunktionsstörung durch eine fehlregulierte Antwort des Körpers auf eine Infektion (…3); …","n":10,"info":"Sepsis: Fieber oder Unterkühlung, Tachykardie, schnelle Atmung, Verwirrtheit, Blutdruckabfall, marmorierte Haut, wenig Urin."}]},{"id":"med-de-5","cat":"med","lang":"de","level":4,"title":"Herz, Gefäße & Blut V","w":19,"h":17,"x":11,"entries":[{"d":"a","r":2,"c":0,"a":"AGRANULOZYTOSE","q":"Fast völliges Fehlen neutrophiler Granulozyten (< 500/µl), meist medikamentös ausgelöst (z. B. Metamizol, …","n":6,"info":"Agranulozytose: Plötzlich hohes Fieber, Halsschmerzen, Schleimhautgeschwüre (Angina agranulocytotica), schweres Krankheitsgefühl."},{"d":"a","r":4,"c":6,"a":"IGAVASKULITIS","q":"Häufigste … im Kindesalter: Ablagerung von IgA-Immunkomplexen in kleinen Gefäßen, oft nach einem Atemwegsinfekt","n":7,"info":"IgA-Vaskulitis (Purpura Schönlein-Henoch): Tastbare Purpura an Beinen und Gesäß, Gelenkschmerzen, kolikartige Bauchschmerzen, evtl. Blut im Urin"},{"d":"a","r":10,"c":7,"a":"MYOKARDITIS","q":"Entzündung des …, meist viral (z. B. Parvovirus B19, Enteroviren, SARS-CoV-2), seltener autoimmun, toxisch …","n":11,"info":"Myokarditis (Herzmuskelentzündung): Leistungsknick, Brustschmerz, Herzstolpern, Zeichen der Herzinsuffizienz – oft Tage bis Wochen nach einem Infekt"},{"d":"d","r":0,"c":2,"a":"PURKINJEFASERN","q":"Welche Endaufzweigungen des Erregungsleitungssystems verteilen die Erregung im Kammermyokard?","n":1,"info":"Purkinje-Fasern: Endaufzweigungen des Leitungssystems unter dem Endokard; leiten am schnellsten und erregen das Arbeitsmyokard; Eigenfrequenz ca. 20–40/min."},{"d":"d","r":0,"c":4,"a":"LONGQTSYNDROM","q":"Verlängerte Repolarisation (langes QT-Intervall) mit Gefahr von Torsade-de-pointes-Tachykardien","n":2,"info":"Long-QT-Syndrom: Synkopen oder Krampfanfälle bei Stress, Schreck, Sport (z. B. Schwimmen) oder Weckerklingeln; plötzlicher Herztod"},{"d":"d","r":0,"c":15,"a":"MILZINFARKT","q":"Absterben von Milzgewebe durch Verschluss der Milzarterie oder ihrer Äste – embolisch (Vorhofflimmern, Endokarditis) …","n":3,"info":"Milzinfarkt: Akuter Schmerz im linken Oberbauch, evtl. in die linke Schulter ausstrahlend, Fieber; teils symptomlos"},{"d":"d","r":1,"c":0,"a":"TAWARASCHENKEL","q":"Welche Leitungsbahnen gehen aus dem His-Bündel hervor und ziehen beidseits des Septums zur Herzspitze?","n":4,"info":"Tawara-Schenkel: Rechter und linker Schenkel des Leitungssystems, die beidseits im Kammerseptum zur Herzspitze ziehen; ihre Blockade heißt Schenkelblock."},{"d":"d","r":1,"c":7,"a":"HODGKINLYMPHOM","q":"Bösartiges … mit wenigen großen Tumorzellen (… und Reed-Sternberg-Zellen, B-Zell-Ursprung) in …","n":5,"info":"Hodgkin-Lymphom (Morbus Hodgkin): Schmerzlose, gummiartige Lymphknotenschwellung (oft Hals, Mediastinum), B-Symptome, Juckreiz, selten Schmerz nach Alkohol."},{"d":"d","r":7,"c":13,"a":"RANDSINUS","q":"In welchen Raum direkt unter der Kapsel mündet die zuführende Lymphe?","n":8,"info":"Randsinus: Sinus direkt unter der Kapsel, in den die zuführenden Lymphgefäße münden; hier siedeln sich Tumorzellen oft zuerst an."},{"d":"d","r":7,"c":17,"a":"WPWSYNDROM","q":"Angeborene zusätzliche Leitungsbahn (Kent-Bündel) zwischen Vorhof und Kammer, die den AV-Knoten umgeht","n":9,"info":"WPW-Syndrom (Wolff-Parkinson-White): Anfallsartiges Herzrasen mit plötzlichem Beginn und Ende, Schwindel; selten Synkope oder plötzlicher Herztod"},{"d":"d","r":8,"c":10,"a":"AVKNOTEN","q":"Welche Struktur verzögert die Erregungsüberleitung von den Vorhöfen auf die Kammern?","n":10,"info":"AV-Knoten: Im Boden des rechten Vorhofs (Koch-Dreieck); verzögert die Erregung, damit die Kammern nach den Vorhöfen kontrahieren; Ersatzrhythmus ca. 40–60/min."}]},{"id":"med-de-6","cat":"med","lang":"de","level":4,"title":"Herz, Gefäße & Blut VI","w":24,"h":14,"x":11,"entries":[{"d":"a","r":1,"c":3,"a":"BURKITTLYMPHOM","q":"Hochaggressives B-Zell-… mit MYC-Translokation (meist t(8;14)); endemisch in Afrika (EBV, Malaria, …","n":3,"info":"Burkitt-Lymphom: Rasch wachsender Tumor (innerhalb von Tagen), endemisch am Kiefer, sporadisch als Raumforderung im Bauch mit Schmerzen."},{"d":"a","r":3,"c":12,"a":"WALDENSTROEM","q":"Morbus …: Lymphoplasmozytisches Lymphom mit Bildung von monoklonalem IgM; meist ältere Männer, fast immer …","n":7,"info":"Morbus Waldenström: Müdigkeit (Anämie), Hyperviskositätssyndrom: Sehstörungen, Kopfschmerz, Schleimhautblutungen; Polyneuropathie."},{"d":"a","r":5,"c":0,"a":"VENENKLAPPE","q":"Welche Strukturen in den Beinvenen verhindern das Zurückfließen des Blutes?","n":8,"info":"Venenklappe: Taschenförmige Intimafalten v. a. in Extremitätenvenen, die den Rückfluss verhindern; ihr Versagen begünstigt Krampfadern (Varizen)."},{"d":"a","r":6,"c":12,"a":"HISBUENDEL","q":"Welcher Teil des Leitungssystems durchbohrt das Herzskelett?","n":9,"info":"His-Bündel: Einzige elektrische Verbindung durch das bindegewebige Herzskelett von den Vorhöfen zu den Kammern."},{"d":"a","r":8,"c":13,"a":"NEBENMILZ","q":"Angeborenes, versprengtes Milzgewebe außerhalb der Milz, meist am Milzhilus; häufig (etwa jeder Zehnte) und harmlos","n":10,"info":"Nebenmilz (Lien accessorius): Keine Beschwerden – Zufallsbefund; selten Stieldrehung oder Verwechslung mit Tumor oder Lymphknoten"},{"d":"a","r":10,"c":13,"a":"MILZABSZESS","q":"Eiteransammlung in der Milz, meist durch Streuung über das Blut (v. a. Endokarditis), seltener nach Infarkt oder …","n":11,"info":"Milzabszess: Fieber, Schmerzen im linken Oberbauch, Leukozytose; linksseitiger Pleuraerguss möglich"},{"d":"d","r":0,"c":7,"a":"MILZHAEMANGIOM","q":"Häufigster gutartiger Tumor der Milz aus erweiterten Blutgefäßen; meist klein und zufällig entdeckt","n":1,"info":"Milzhämangiom: Meist symptomlos; große Befunde: Druckgefühl links, selten Ruptur oder Thrombozytenverbrauch"},{"d":"d","r":0,"c":14,"a":"THALASSAEMIE","q":"Erbliche Störung der Globinkettenbildung: Beta-… (v. a. Mittelmeerraum) oder Alpha-… (v. a. …","n":2,"info":"Thalassämie: Minor: leichte Mikrozytose ohne Beschwerden; Major: ab 1. Lebensjahr schwere Anämie, Gedeihstörung, große Leber/Milz, Knochenveränderungen."},{"d":"d","r":1,"c":9,"a":"TLYMPHOZYTEN","q":"Welche Abwehrzellen reifen im Thymus und erkennen Antigen nur zusammen mit MHC?","n":4,"info":"T-Lymphozyten (CD4/CD8): CD4-Helferzellen steuern die Abwehr (über MHC II), CD8-zytotoxische Zellen töten infizierte Zellen (über MHC I)."},{"d":"d","r":3,"c":2,"a":"SINUSKNOTEN","q":"Wo entsteht normalerweise der Herzschlag?","n":5,"info":"Sinusknoten: Primärer Schrittmacher in der Wand des rechten Vorhofs nahe der Mündung der V. cava sup.; Eigenfrequenz ca. 60–80/min."},{"d":"d","r":3,"c":4,"a":"MONOZYT","q":"Welche Blutzelle wird im Gewebe zum Makrophagen?","n":6,"info":"Monozyt: Größter Leukozyt mit nierenförmigem Kern; wandert ins Gewebe aus und wird dort zum Makrophagen."}]},{"id":"med-de-7","cat":"med","lang":"de","level":2,"title":"Atmung & Sinne I","w":15,"h":18,"x":11,"entries":[{"d":"a","r":1,"c":1,"a":"PNEUMONIE","q":"Akute Infektion des Lungengewebes (Alveolen/Interstitium), … meist durch …, seltener Haemophilus, …","n":2,"info":"Pneumonie (ambulant erworben): Fieber, Husten mit eitrigem Auswurf, Atemnot, atemabhängiger Thoraxschmerz; bei Älteren oft nur Verwirrtheit."},{"d":"a","r":3,"c":0,"a":"INFLUENZA","q":"Akute Infektion mit … A oder B, saisonal im Winter, Tröpfchen/Aerosole; gefährlich v. a. für Ältere, …","n":3,"info":"Influenza (echte Grippe): Plötzlicher Beginn mit hohem Fieber, Schüttelfrost, starken Kopf- und Gliederschmerzen, trockenem Husten."},{"d":"a","r":5,"c":1,"a":"PRESBYOPIE","q":"… Verlust der Fähigkeit zur Naheinstellung (Akkommodation), weil die Linse an Elastizität verliert; …","n":4,"info":"Presbyopie (Alterssichtigkeit): Lesen in der Nähe wird mühsam, Text muss weiter weggehalten werden (die Arme werden zu kurz), v.a. bei schlechtem Licht"},{"d":"a","r":7,"c":1,"a":"ERKAELTUNG","q":"Virale … der oberen Atemwege (v. a. Rhino-, Corona-, Adenoviren) durch Tröpfchen und Hände","n":5,"info":"Erkältung (grippaler Infekt): Schnupfen, Halskratzen, Husten, leichtes Krankheitsgefühl, allenfalls mäßiges Fieber."},{"d":"a","r":8,"c":11,"a":"COPD","q":"…, nicht vollständig reversible Atemwegs… aus … Bronchitis und/oder …","n":7,"info":"COPD (chronisch obstruktive Lungenerkrankung): AHA-Symptome: Auswurf, Husten, Atemnot (zunächst bei Belastung); gehäufte Infekte und Exazerbationen."},{"d":"a","r":12,"c":1,"a":"KONJUNKTIVITIS","q":"Häufige Entzündung der …: viral (Adenoviren, sehr ansteckend), bakteriell, allergisch (z.B. Heuschnupfen) …","n":10,"info":"Konjunktivitis (Bindehautentzündung): Rotes Auge, Fremdkörpergefühl, Tränen oder Ausfluss, verklebte Lider; Sehschärfe normal, kein starker Schmerz"},{"d":"d","r":0,"c":3,"a":"KEHLDECKEL","q":"Welche Struktur verschließt beim Schlucken den Kehlkopfeingang?","n":1,"info":"Kehldeckel (Epiglottis): Blattförmiger elastischer Knorpel, der beim Schlucken den Kehlkopfeingang abdeckt und so vor Aspiration schützt."},{"d":"d","r":5,"c":1,"a":"PRESBYAKUSIS","q":"Langsam fortschreitende, beidseitige Innenohrschwerhörigkeit im Alter durch Verlust von Haarzellen und Nervenfasern; …","n":4,"info":"Presbyakusis (Altersschwerhörigkeit): Beidseitige Hörminderung zuerst für hohe Töne, schlechtes Sprachverstehen in Gesellschaft und bei Störgeräuschen, oft Tinnitus"},{"d":"d","r":7,"c":12,"a":"HOERSTURZ","q":"Plötzliche, meist einseitige Innenohrschwerhörigkeit ohne erkennbare Ursache; diskutiert werden …","n":6,"info":"Hörsturz (akuter idiopathischer Hörverlust): Plötzliche einseitige Hörminderung bis Taubheit, Watte- oder Druckgefühl im Ohr, oft Tinnitus, manchmal Schwindel"},{"d":"d","r":9,"c":5,"a":"SINUSITIS","q":"Entzündung der …, meist viral nach Erkältung (Rhino…), selten bakteriell; chronisch bei …","n":8,"info":"Sinusitis (Nasennebenhöhlenentzündung): Verstopfte Nase, eitriges Sekret, Gesichts-/Stirnschmerz, der beim Bücken zunimmt; Riechstörung."},{"d":"d","r":10,"c":8,"a":"KATARAKT","q":"Trübung der Augenlinse, meist altersbedingt; weitere Ursachen: Diabetes, Kortison, UV-Licht, Rauchen, Trauma, …","n":9,"info":"Katarakt (Grauer Star): Langsam zunehmendes Verschwommen- und Nebelsehen, Blendempfindlichkeit (Gegenlicht, nachts), blasse Farben"}]},{"id":"med-de-8","cat":"med","lang":"de","level":3,"title":"Atmung & Sinne II","w":18,"h":14,"x":11,"entries":[{"d":"a","r":0,"c":3,"a":"TROMMELFELL","q":"Welche Membran trennt Gehörgang und Paukenhöhle?","n":1,"info":"Trommelfell: Dünne Membran zwischen Außen- und Mittelohr; mit ihr ist der Hammergriff verwachsen, der die Schwingung weiterleitet."},{"d":"a","r":4,"c":0,"a":"ZILIARKOERPER","q":"Welche Struktur bildet das Kammerwasser?","n":7,"info":"Ziliarkörper: Enthält den M. ciliaris – seine Kontraktion entspannt die Zonulafasern (Naheinstellung) – und bildet das Kammerwasser."},{"d":"a","r":7,"c":8,"a":"OHRMUSCHEL","q":"Welcher Teil des äußeren Ohrs besteht aus elastischem Knorpel?","n":9,"info":"Ohrmuschel: Elastischer Knorpel mit Hautüberzug (nur das Ohrläppchen ist knorpelfrei); fängt Schall und hilft beim Richtungshören."},{"d":"d","r":0,"c":5,"a":"OHRTROMPETE","q":"Welcher Gang sorgt für den Druckausgleich im Mittelohr?","n":2,"info":"Ohrtrompete (Tuba auditiva): Verbindet Paukenhöhle und Nasenrachen; öffnet sich beim Schlucken und gleicht den Druck aus; bei Kindern kürzer und flacher."},{"d":"d","r":0,"c":12,"a":"LEDERHAUT","q":"Welche weiße Augenhaut gibt dem Augapfel seine Form?","n":3,"info":"Lederhaut (Sklera): Weiße, derbe äußere Augenhaut aus straffem Kollagen; gibt dem Augapfel seine Form und dient den Augenmuskeln als Ansatz."},{"d":"d","r":2,"c":3,"a":"STIMMLIPPEN","q":"Welche Falten im Kehlkopf erzeugen durch Schwingung die Stimme?","n":4,"info":"Stimmlippen: Paarige Falten mit Lig. vocale und M. vocalis; ihre Schwingung im Luftstrom erzeugt die Stimme, der Spalt dazwischen heißt Glottis."},{"d":"d","r":2,"c":8,"a":"PNEUMOTHORAX","q":"Luft im Pleuraspalt, die Lunge fällt teilweise zusammen","n":5,"info":"Pneumothorax (Spontanpneumothorax): Plötzlicher einseitiger, stechender Thoraxschmerz und Atemnot."},{"d":"d","r":3,"c":1,"a":"TINNITUS","q":"Wahrnehmung von Geräuschen ohne äußere Schallquelle; meist subjektiv und Folge einer Hörstörung (Lärm, Alter, …","n":6,"info":"Tinnitus (Ohrgeräusch): Pfeifen, Rauschen oder Brummen im Ohr oder Kopf, oft bei Stille stärker; bei hoher Belastung Schlaf- und Konzentrationsstörung"},{"d":"d","r":5,"c":15,"a":"SEHNERV","q":"Welcher Hirnnerv leitet die visuellen Signale vom Auge weg?","n":8,"info":"Sehnerv (N. opticus): Hirnnerv II – eigentlich eine Bahn des ZNS mit Myelin aus Oligodendrozyten; zieht zum Chiasma opticum."},{"d":"d","r":7,"c":10,"a":"RACHEN","q":"Wo kreuzen sich Atemweg und Speiseweg?","n":10,"info":"Rachen (Pharynx): Muskelschlauch mit drei Etagen (Naso-, Oro-, Laryngopharynx); hier kreuzen sich Luft- und Speiseweg."},{"d":"d","r":7,"c":17,"a":"LINSE","q":"Welche elastische Struktur ändert bei der Nahsicht ihre Krümmung?","n":11,"info":"Linse: Bikonvex und elastisch, an Zonulafasern aufgehängt; ändert ihre Brechkraft zur Akkommodation, ihre Trübung heißt Katarakt."}]},{"id":"med-de-9","cat":"med","lang":"de","level":3,"title":"Atmung & Sinne III","w":13,"h":23,"x":11,"entries":[{"d":"a","r":6,"c":5,"a":"TRACHEA","q":"Welches Rohr leitet die Luft vom Kehlkopf zu den Hauptbronchien?","n":4,"info":"Trachea: Ca. 10–12 cm lange Luftröhre mit hufeisenförmigen Knorpelspangen, hinten durch die Pars membranacea (M. trachealis) verschlossen."},{"d":"a","r":9,"c":1,"a":"RINGKNORPEL","q":"Welcher Kehlkopfknorpel ist ein vollständig geschlossener Ring?","n":5,"info":"Ringknorpel: Einziger geschlossener Knorpelring der Atemwege, Basis des Kehlkopfs auf Höhe C6; darunter beginnt die Trachea."},{"d":"a","r":12,"c":0,"a":"BRONCHIALBAUM","q":"Wie nennt man das sich immer weiter aufzweigende System der Atemwege in der Lunge?","n":8,"info":"Bronchialbaum: Verzweigt sich über ca. 23 Generationen: Haupt-, Lappen-, Segmentbronchien bis zu den Bronchiolen; der Knorpel nimmt nach peripher ab."},{"d":"a","r":15,"c":0,"a":"PAUKENERGUSS","q":"Flüssigkeit im Mittelohr ohne akute Entzündungszeichen durch gestörte Belüftung (Tubenfunktionsstörung), häufig bei …","n":10,"info":"Paukenerguss (Seromukotympanon): Hörminderung, Druckgefühl, Kind reagiert schlecht auf Ansprache, verzögerte Sprachentwicklung; keine Schmerzen, kein Fieber"},{"d":"a","r":19,"c":6,"a":"PLEURA","q":"Welche seröse Haut ermöglicht das reibungsarme Gleiten der Lunge an der Brustwand?","n":11,"info":"Pleura (visceralis & parietalis): Seröse Haut: Pleura visceralis überzieht die Lunge, Pleura parietalis die Thoraxwand; dazwischen ein Spalt mit Unterdruck. Nur die parietale ist schmerzempfindlich."},{"d":"d","r":0,"c":7,"a":"BIFURKATION","q":"Wo teilt sich die Luftröhre in die beiden Hauptbronchien?","n":1,"info":"Bifurkation (Carina): Teilungsstelle der Trachea in die Hauptbronchien etwa auf Höhe Th4/5; die Carina ist ein sehr empfindlicher Hustenauslöser."},{"d":"d","r":2,"c":1,"a":"GLASKOERPER","q":"Welche gallertige Masse füllt das Augeninnere hinter der Linse?","n":2,"info":"Glaskörper: Gallertiger, klarer Inhalt aus Wasser, Kollagen und Hyaluronsäure; füllt den größten Teil des Augapfels."},{"d":"d","r":5,"c":11,"a":"MAKULA","q":"Wo liegt der Ort des schärfsten Sehens?","n":3,"info":"Makula (Fovea centralis): Gelber Fleck am hinteren Pol; die Fovea enthält nur Zapfen und ist der Ort des schärfsten Sehens."},{"d":"d","r":11,"c":4,"a":"SCHNECKE","q":"In welchem Teil des Innenohrs liegt das Hörorgan?","n":6,"info":"Schnecke (Cochlea): Knöcherner Gang mit 2,5 Windungen und dem Corti-Organ; hohe Töne werden an der Basis, tiefe an der Spitze registriert."},{"d":"d","r":11,"c":6,"a":"MITTELLAPPEN","q":"Welcher Lappen existiert nur in der rechten Lunge?","n":7,"info":"Mittellappen: Nur rechts vorhanden (Segmente 4 und 5); liegt zwischen Fissura horizontalis und Fissura obliqua und grenzt an das Herz."},{"d":"d","r":12,"c":8,"a":"LUNGENOEDEM","q":"Flüssigkeitsaustritt in Interstitium und Alveolen; meist kardial (Linksherzinsuffizienz, hypertensive Krise), …","n":9,"info":"Lungenödem: Akute Atemnot, Orthopnoe, schaumiges, ggf. rötliches Sputum, Angst, Kaltschweißigkeit."}]},{"id":"med-de-10","cat":"med","lang":"de","level":3,"title":"Atmung & Sinne IV","w":23,"h":14,"x":11,"entries":[{"d":"a","r":1,"c":12,"a":"PSEUDOKRUPP","q":"Virale Entzündung mit Schwellung unterhalb der Stimmlippen bei Kleinkindern (ca. 6 Monate bis 3 Jahre), v. a. …","n":7,"info":"Pseudokrupp (subglottische Laryngitis): Bellender Husten, inspiratorischer Stridor, Heiserkeit, meist nur leichtes Fieber."},{"d":"a","r":3,"c":0,"a":"REGENBOGENHAUT","q":"Welche Struktur reguliert als Blende die Pupillenweite?","n":8,"info":"Regenbogenhaut (Iris): Pigmentierte Blende mit M. sphincter pupillae (parasympathisch, Miosis) und M. dilatator pupillae (sympathisch, Mydriasis)."},{"d":"a","r":4,"c":14,"a":"NETZHAUT","q":"In welcher Augenschicht wird Licht in Nervensignale umgewandelt?","n":9,"info":"Netzhaut (Retina): Innere Augenhaut mit Photorezeptoren und nachgeschalteten Neuronen, deren Axone den Sehnerv bilden; eine Ablösung ist ein Notfall."},{"d":"a","r":6,"c":15,"a":"HORNHAUT","q":"Welcher Teil des Auges besitzt die größte Brechkraft?","n":10,"info":"Hornhaut (Cornea): Klare, gefäßfreie Vorderfläche mit der größten Brechkraft (ca. 43 dpt); sensibel über N. V1 (Kornealreflex)."},{"d":"d","r":0,"c":6,"a":"HYPOSPHAGMA","q":"Harmlose flächige Blutung unter der … durch Platzen eines kleinen Gefäßes, z.B. nach Pressen, Husten, Niesen …","n":1,"info":"Hyposphagma (Bindehautunterblutung): Scharf begrenzter, leuchtend roter Fleck auf dem Augenweiß, keine Schmerzen, keine Sehstörung"},{"d":"d","r":0,"c":8,"a":"NASENBLUTEN","q":"Blutung aus der Nase, meist vorn aus dem Gefäßgeflecht am Septum (Locus Kiesselbachi)","n":2,"info":"Nasenbluten (Epistaxis): Blutung aus einem oder beiden Nasenlöchern, ggf. Blut im Rachen (hintere Blutung)."},{"d":"d","r":0,"c":15,"a":"LUNGENHILUS","q":"An welcher Stelle treten Bronchus und Lungengefäße in die Lunge ein?","n":3,"info":"Lungenhilus: Ein- und Austrittsstelle an der medialen Lungenfläche für Hauptbronchus, A. und Vv. pulmonales, Bronchialgefäße, Nerven und Lymphgefäße."},{"d":"d","r":1,"c":1,"a":"PLEURAERGUSS","q":"Flüssigkeit im …: Transsudat (v. a. Herzinsuffizienz, Leberzirrhose, Hypoalbuminämie) oder Exsudat …","n":4,"info":"Pleuraerguss: Atemnot je nach Menge, Druck- oder atemabhängiger Schmerz; einseitig abgeschwächtes Atemgeräusch."},{"d":"d","r":1,"c":4,"a":"TONSILLITIS","q":"Entzündung der Gaumen…, häufig viral; bakteriell v. a. durch Streptococcus pyogenes (Gruppe-A-Streptokokken, …","n":5,"info":"Tonsillitis (Mandelentzündung): Starke Halsschmerzen, Schluckbeschwerden, Fieber; gerötete, geschwollene Mandeln mit Belägen."},{"d":"d","r":1,"c":10,"a":"SCHILDKNORPEL","q":"Welcher Kehlkopfknorpel bildet den Adamsapfel?","n":6,"info":"Schildknorpel: Größter Kehlkopfknorpel aus hyalinem Knorpel; beim Mann als Adamsapfel (Prominentia laryngea) tastbar."},{"d":"d","r":1,"c":12,"a":"PAUKENHOEHLE","q":"Welcher luftgefüllte Raum enthält die Gehörknöchelchen?","n":7,"info":"Paukenhöhle: Luftgefüllter Mittelohrraum mit den Gehörknöchelchen; über die Tuba auditiva mit dem Rachen verbunden."}]},{"id":"med-de-11","cat":"med","lang":"de","level":4,"title":"Atmung & Sinne V","w":15,"h":21,"x":11,"entries":[{"d":"a","r":0,"c":3,"a":"BOGENGAENGE","q":"Welche Teile des Labyrinths registrieren Drehbeschleunigungen?","n":1,"info":"Bogengänge: Drei annähernd senkrecht zueinander stehende Gänge, deren Ampullen Drehbeschleunigungen registrieren."},{"d":"a","r":5,"c":1,"a":"LARYNXKARZINOM","q":"Meist Plattenepithelkarzinom des …, einer der häufigsten Kopf-Hals-Tumoren","n":6,"info":"Larynxkarzinom (Kehlkopfkrebs): Heiserkeit > 3 Wochen (glottisch, früh), später Schluckbeschwerden, Atemnot/Stridor, Halsknoten."},{"d":"a","r":13,"c":0,"a":"SARKOIDOSE","q":"Systemerkrankung unklarer Ursache mit nicht-verkäsenden epitheloidzelligen Granulomen, v. a. in Lunge und …","n":8,"info":"Sarkoidose (Morbus Boeck): Oft symptomlos (Zufallsbefund); trockener Husten, Belastungsdyspnoe, Müdigkeit; akut: Fieber, Gelenkschmerzen, Erythema nodosum."},{"d":"a","r":18,"c":0,"a":"ZAPFEN","q":"Welche Photorezeptoren ermöglichen das Farbensehen?","n":10,"info":"Zapfen: Ca. 6 Mio. Photorezeptoren für Farb- und Scharfsehen in drei Typen (S, M, L); konzentriert in der Fovea."},{"d":"d","r":0,"c":3,"a":"BECHERZELLEN","q":"Welche Epithelzellen der Atemwege produzieren den Schleim?","n":1,"info":"Becherzellen: Schleimbildende Zellen im respiratorischen Epithel; bei Rauchern und chronischer Bronchitis vermehrt."},{"d":"d","r":2,"c":9,"a":"ZWERCHFELL","q":"Welcher Muskel wird vom N. phrenicus innerviert?","n":2,"info":"Zwerchfell: Wichtigster Atemmuskel, innerviert vom N. phrenicus (C3–C5); seine Kontraktion senkt die Kuppeln und vergrößert den Thorax."},{"d":"d","r":3,"c":7,"a":"MUKOVISZIDOSE","q":"Autosomal-rezessive Erbkrankheit durch Mutationen im CFTR-Chloridkanal (häufigste F508del): zäher Schleim in Lunge, …","n":3,"info":"Mukoviszidose (zystische Fibrose): Chronischer Husten, wiederkehrende Lungeninfekte, Gedeihstörung, fettige Stühle; Mekoniumileus beim Neugeborenen."},{"d":"d","r":4,"c":1,"a":"ALVEOLE","q":"In welchen Bläschen findet der Gasaustausch statt?","n":4,"info":"Alveole: Lungenbläschen, kleinste Einheit des Gasaustauschs; Wand aus Typ-I- und Typ-II-Pneumozyten, dicht umsponnen von Kapillaren."},{"d":"d","r":4,"c":11,"a":"PIGMENTEPITHEL","q":"Welche Netzhautschicht recycelt Vitamin-A-Derivate für die Photorezeptoren?","n":5,"info":"Pigmentepithel: Äußerste Netzhautschicht; phagozytiert Außensegmente der Photorezeptoren, regeneriert Retinal (Vitamin A) und absorbiert Streulicht."},{"d":"d","r":9,"c":5,"a":"CORTIORGAN","q":"Welches Sinnesepithel auf der Basilarmembran wandelt Schall in Erregung um?","n":7,"info":"Corti-Organ: Sinnesepithel auf der Basilarmembran mit inneren und äußeren Haarzellen, bedeckt von der Tektorialmembran."},{"d":"d","r":13,"c":1,"a":"ADERHAUT","q":"Welche gefäßreiche Schicht ernährt die Photorezeptoren?","n":9,"info":"Aderhaut (Choroidea): Gefäßreiche Schicht zwischen Sklera und Netzhaut; versorgt die äußeren Netzhautschichten mit den Photorezeptoren."}]},{"id":"med-de-12","cat":"med","lang":"de","level":4,"title":"Atmung & Sinne VI","w":18,"h":15,"x":11,"entries":[{"d":"a","r":0,"c":4,"a":"CHOLESTEATOM","q":"Einwachsen von verhornendem Plattenepithel ins Mittelohr (Knocheneiterung), meist erworben bei chronischer …","n":1,"info":"Cholesteatom: Chronischer, übelriechender Ohrausfluss, zunehmende Schwerhörigkeit, kaum Schmerzen"},{"d":"a","r":3,"c":0,"a":"KINOZILIEN","q":"Welche Zellfortsätze transportieren den Schleim in den Atemwegen zum Rachen?","n":4,"info":"Kinozilien (Flimmerhärchen): Bewegliche Zellfortsätze mit 9×2+2-Mikrotubuli; schlagen koordiniert rachenwärts und transportieren den Schleim (mukoziliäre Clearance)."},{"d":"a","r":5,"c":4,"a":"BRONCHIEKTASEN","q":"Bleibende Erweiterung der … mit gestörter Schleimreinigung und chronischer Infektion","n":9,"info":"Bronchiektasen: Chronischer Husten mit reichlich, morgens 'maulvollem' eitrigem Auswurf, wiederkehrende Infekte, Bluthusten."},{"d":"a","r":11,"c":0,"a":"STAEBCHEN","q":"Welche Photorezeptoren ermöglichen das Sehen in der Dämmerung?","n":10,"info":"Stäbchen: Ca. 120 Mio. Photorezeptoren für Dämmerungs- und Nachtsehen (Rhodopsin); fehlen in der Fovea."},{"d":"d","r":0,"c":7,"a":"LEGIONELLOSE","q":"Atypische Pneumonie durch … pneumophila, übertragen durch Einatmen erregerhaltiger Aerosole aus warmem …","n":2,"info":"Legionellose (Legionärskrankheit): Hohes Fieber, trockener Husten, Kopfschmerz, Verwirrtheit, Durchfall; Pontiac-Fieber als milde Form ohne Pneumonie."},{"d":"d","r":0,"c":12,"a":"ARDS","q":"Akute, diffuse Entzündung der alveolokapillären Membran mit nicht-kardialem …","n":3,"info":"ARDS (akutes Lungenversagen): Rasch zunehmende schwere Atemnot und Hypoxämie, die auf Sauerstoffgabe kaum anspricht."},{"d":"d","r":3,"c":0,"a":"KERATITIS","q":"Entzündung der … durch Bakterien (z.B. Pseudomonas), Viren (Herpes simplex), Pilze oder Akanthamöben; …","n":4,"info":"Keratitis (Hornhautentzündung): Starke Schmerzen, Lichtscheu, Tränen, Sehverschlechterung, Fremdkörpergefühl; weißes Hornhautinfiltrat"},{"d":"d","r":4,"c":11,"a":"KEUCHHUSTEN","q":"Hoch ansteckende Infektion mit Bordetella … (Toxin), Tröpfchenübertragung; auch bei Erwachsenen, da der …","n":5,"info":"Keuchhusten (Pertussis): Nach Erkältungsphase stakkatoartige Hustenanfälle mit ziehendem Einatmen ('Juchzen') und Erbrechen; Husten oft wochenlang."},{"d":"d","r":4,"c":13,"a":"OTOSKLEROSE","q":"Umbau des Knochens der Innenohrkapsel mit Fixierung des Steigbügels im ovalen Fenster; familiär gehäuft, Frauen …","n":6,"info":"Otosklerose: Langsam zunehmende, oft beidseitige Schallleitungsschwerhörigkeit im jungen Erwachsenenalter, Tinnitus; im Lärm besseres Verstehen"},{"d":"d","r":4,"c":15,"a":"ASBESTOSE","q":"Lungenfibrose durch jahrelang eingeatmete … (früher Bau, Werften, Isolierung; in Deutschland seit 1993 …","n":7,"info":"Asbestose: Langsam zunehmende Belastungsdyspnoe, trockener Husten, basales Knisterrasseln."},{"d":"d","r":4,"c":17,"a":"ENDOLYMPHE","q":"Welche kaliumreiche Flüssigkeit füllt das häutige Labyrinth?","n":8,"info":"Endolymphe: Kaliumreiche Flüssigkeit im häutigen Labyrinth; das positive endocochleäre Potenzial treibt die Erregung der Haarzellen."}]},{"id":"med-de-13","cat":"med","lang":"de","level":5,"title":"Atmung & Sinne VII","w":19,"h":17,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"TUBERKULOSE","q":"Meldepflichtige Infektion mit Mycobacterium tuberculosis (aerogen), meist der Lunge; oft jahrelang latent, …","n":1,"info":"Tuberkulose: B-Symptomatik (Fieber, Nachtschweiß, Gewichtsverlust), Husten > 3 Wochen, Bluthusten."},{"d":"a","r":2,"c":6,"a":"DIPHTHERIE","q":"Toxinbedingte Infektion durch Corynebacterium … (Tröpfchen); in Deutschland dank Impfung selten, Fälle v. …","n":4,"info":"Diphtherie: Halsschmerzen, Fieber, grauweiße, festhaftende Pseudomembranen auf den Mandeln, süßlicher Mundgeruch, 'Cäsarenhals'."},{"d":"a","r":4,"c":8,"a":"KERATOKONUS","q":"Fortschreitende kegelförmige Vorwölbung und Verdünnung der Hornhaut, Beginn meist in Pubertät oder jungem …","n":8,"info":"Keratokonus: Zunehmend verzerrtes, unscharfes Sehen, häufig wechselnde Brillenwerte, irregulärer Astigmatismus, Blendempfindlichkeit"},{"d":"a","r":6,"c":0,"a":"TYPIIPNEUMOZYT","q":"Welche Alveolarzellen verhindern durch ihr Sekret den Kollaps der Alveolen?","n":9,"info":"Typ-II-Pneumozyt (Surfactant): Kubische Zellen, die Surfactant bilden (senkt die Oberflächenspannung) und als Vorläufer verlorene Typ-I-Zellen ersetzen."},{"d":"a","r":8,"c":8,"a":"MASTOIDITIS","q":"Eitrige Entzündung von Schleimhaut und Knochen im Warzenfortsatz (…) als Komplikation einer akuten …","n":11,"info":"Mastoiditis: Schmerzhafte Schwellung und Rötung hinter dem Ohr, abstehende Ohrmuschel, Fieber, Ohrausfluss, erneute Verschlechterung"},{"d":"d","r":0,"c":9,"a":"SCHLEMMKANAL","q":"Über welchen Ringsinus im Kammerwinkel fließt das Kammerwasser hauptsächlich ab?","n":2,"info":"Schlemm-Kanal: Ringförmiger Venensinus im Kammerwinkel; Hauptabflussweg des Kammerwassers – eine Abflussstörung führt zum Glaukom."},{"d":"d","r":2,"c":2,"a":"XEROPHTHALMIE","q":"… durch …; weltweit häufigste vermeidbare Erblindungsursache bei Kindern in Regionen mit …","n":3,"info":"Xerophthalmie (Vitamin-A-Mangel am Auge): Zuerst Nachtblindheit, dann trockene Bindehaut und Hornhaut, Bitôt-Flecken, schließlich Hornhauterweichung"},{"d":"d","r":3,"c":4,"a":"TYPIPNEUMOZYT","q":"Welche flachen Zellen bedecken den Großteil der Alveolarwand?","n":5,"info":"Typ-I-Pneumozyt: Flache Deckzellen, die ca. 95 % der Alveolaroberfläche bedecken und eine sehr kurze Diffusionsstrecke bilden; nicht teilungsfähig."},{"d":"d","r":4,"c":0,"a":"RETINOBLASTOM","q":"Häufigster bösartiger Augentumor im Kindesalter, meist vor dem 5. Lebensjahr; entsteht durch Verlust beider Kopien …","n":6,"info":"Retinoblastom: Weißes Aufleuchten der Pupille (Leukokorie), z.B. auf Blitzlichtfotos; Schielen"},{"d":"d","r":4,"c":6,"a":"LUNGENEMBOLIE","q":"Verschluss von …, meist durch ein Gerinnsel aus einer tiefen Beinvenenthrombose","n":7,"info":"Lungenembolie: Plötzliche Atemnot, Tachypnoe, atemabhängiger Thoraxschmerz, Tachykardie; ggf. Synkope, Bluthusten."},{"d":"d","r":7,"c":15,"a":"SILIKOSE","q":"Staublungenerkrankung durch jahrelanges Einatmen von Quarzfeinstaub (Bergbau, Steinbearbeitung, Sandstrahlen, …","n":10,"info":"Silikose (Quarzstaublunge): Jahre nach Exposition zunehmende Belastungsdyspnoe und Husten; lange beschwerdearm."}]},{"id":"med-de-14","cat":"med","lang":"de","level":3,"title":"Verdauung I","w":17,"h":18,"x":11,"entries":[{"d":"a","r":1,"c":0,"a":"DUODENUM","q":"Welcher Abschnitt direkt hinter dem Pylorus ist häufigster Sitz von Zwölffingerdarmgeschwüren?","n":2,"info":"Duodenum (Bulbus): Erster, intraperitoneal gelegener Teil des Duodenums direkt hinter dem Pylorus; häufigster Sitz von Ulcera duodeni."},{"d":"a","r":2,"c":8,"a":"PFORTADER","q":"Welche Vene bringt das Blut aus dem Darm zur Leber?","n":5,"info":"Pfortader (V. portae): Entsteht hinter dem Pankreas aus V. mesenterica sup. und V. lienalis; bringt nährstoffreiches Blut aus Darm, Magen und Milz zur Leber."},{"d":"a","r":5,"c":2,"a":"DIVERTIKULITIS","q":"Entzündung von Dickdarm… (meist Sigma); unkompliziert oder kompliziert durch Abszess, Perforation, Fistel …","n":6,"info":"Divertikulitis: Schmerz im linken Unterbauch („Linksappendizitis“), Fieber, veränderter Stuhlgang, tastbare Walze"},{"d":"a","r":8,"c":1,"a":"LEBERZIRRHOSE","q":"Endstadium chronischer Lebererkrankungen: bindegewebiger Umbau mit Regeneratknoten zerstört die Läppchenstruktur","n":7,"info":"Leberzirrhose: Müdigkeit, Leberhautzeichen (Spider naevi, Palmarerythem), Ikterus, Aszites, Gynäkomastie, Muskelschwund; später Blutung, Verwirrtheit."},{"d":"a","r":10,"c":5,"a":"SPEISEROEHRE","q":"Welches Organ mündet an der Kardia in den Magen?","n":8,"info":"Speiseröhre (Einmündung): Mündet am Ostium cardiacum in den Magen; der spitze His-Winkel und der untere Ösophagussphinkter wirken gegen Reflux."},{"d":"a","r":14,"c":0,"a":"GALLENSTEINE","q":"Steine in der …, meist Cholesterinsteine durch übersättigte Galle","n":10,"info":"Gallensteine (Cholezystolithiasis): Meist symptomlos; Gallenkolik: krampfartiger Schmerz im rechten Oberbauch, oft nach fettem Essen, Ausstrahlung in die rechte Schulter."},{"d":"d","r":0,"c":4,"a":"LEBERVENEN","q":"Über welche Gefäße verlässt das Blut die Leber?","n":1,"info":"Lebervenen: Meist drei große Venen (rechte, mittlere, linke), die das Blut der Zentralvenen sammeln und direkt unter dem Zwerchfell in die V. cava inf. münden."},{"d":"d","r":1,"c":10,"a":"CORPUS","q":"Welcher Abschnitt bildet den größten Teil des Magens?","n":3,"info":"Corpus: Größter Magenabschnitt; enthält wie der Fundus die Hauptdrüsen mit Beleg- und Hauptzellen (Säure, Pepsinogen, Intrinsic Factor)."},{"d":"d","r":1,"c":13,"a":"CALOTDREIECK","q":"In welchem Bereich wird bei der Cholezystektomie die A. cystica aufgesucht?","n":4,"info":"Calot-Dreieck: Begrenzt von Ductus cysticus, Ductus hepaticus communis und Leberunterrand; enthält die A. cystica – Orientierungspunkt bei der Cholezystektomie."},{"d":"d","r":5,"c":2,"a":"DIVERTIKULOSE","q":"Ausstülpungen der Schleimhaut durch Muskellücken der Dickdarmwand (Pseudo…), meist im Sigma; mit dem Alter …","n":6,"info":"Divertikulose: Meist symptomlos (Zufallsbefund); selten schmerzlose, kräftige Blutung"},{"d":"d","r":12,"c":6,"a":"MASLD","q":"Leberverfettung (≥5 % der Leberzellen) bei mindestens einem kardio… Risikofaktor (Adipositas, …","n":9,"info":"MASLD (metabolische Fettlebererkrankung, früher NAFLD): Meist symptomlos; evtl. Druckgefühl im rechten Oberbauch, Müdigkeit. Oft Zufallsbefund (erhöhte Leberwerte, helle Leber im Ultraschall)."}]},{"id":"med-de-15","cat":"med","lang":"de","level":3,"title":"Verdauung II","w":16,"h":14,"x":11,"entries":[{"d":"a","r":0,"c":4,"a":"ANTRUM","q":"In welchem Magenabschnitt liegen die meisten Gastrin bildenden Zellen?","n":1,"info":"Antrum: Unterer Abschnitt vor dem Pylorus; enthält die G-Zellen (Gastrin) und durchmischt den Speisebrei kräftig."},{"d":"a","r":4,"c":1,"a":"PANKREASKOPF","q":"Welcher Pankreasteil liegt in der Duodenalschlinge?","n":5,"info":"Pankreaskopf: Liegt in der C-Schlinge des Duodenums rechts der Wirbelsäule; hinten verläuft der Ductus choledochus – Kopftumoren verursachen einen schmerzlosen Ikterus."},{"d":"a","r":10,"c":0,"a":"KARDIA","q":"Wie heißt der Mageneingang?","n":9,"info":"Kardia: Übergangszone von der Speiseröhre in den Magen mit schleimbildenden Kardiadrüsen; liegt etwa auf Höhe Th11."},{"d":"a","r":11,"c":9,"a":"JEJUNUM","q":"Welcher Dünndarmabschnitt folgt direkt auf das Duodenum?","n":10,"info":"Jejunum: Proximale ca. zwei Fünftel des Jejunoileums, eher links oben; hohe, dichte Kerckring-Falten und Hauptort der Nährstoffresorption."},{"d":"d","r":0,"c":4,"a":"ANALKANAL","q":"Welcher letzte Darmabschnitt wird durch zwei Schließmuskeln verschlossen?","n":1,"info":"Analkanal: Ca. 3–4 cm lang; an der Linea dentata Übergang zum Plattenepithel; Verschluss durch inneren (glatten) und äußeren (willkürlichen) Sphinkter."},{"d":"d","r":2,"c":2,"a":"HIATUSHERNIE","q":"Verlagerung von Magenanteilen durch den … oesophageus des Zwerchfells in den Brustraum; meist axiale …","n":2,"info":"Hiatushernie: Oft symptomlos; axial: Refluxbeschwerden; paraösophageal: Druckgefühl, Völle, Dysphagie, Anämie"},{"d":"d","r":3,"c":7,"a":"GALLENBLASE","q":"Welches Hohlorgan an der Leberunterfläche speichert und konzentriert die Galle?","n":3,"info":"Gallenblase: Birnenförmiges Speicherorgan an der Leberunterfläche; konzentriert die Galle und entleert sich nach CCK-Reiz."},{"d":"d","r":3,"c":10,"a":"ZOELIAKIE","q":"Immunvermittelte Systemerkrankung mit lebenslanger Glutenunverträglichkeit bei genetischer Veranlagung …","n":4,"info":"Zöliakie: Durchfall, Blähungen, Gewichtsverlust, Gedeihstörung bei Kindern; oft nur Eisenmangel und Müdigkeit"},{"d":"d","r":4,"c":12,"a":"FUNDUS","q":"Welcher Magenabschnitt enthält im Stehen typischerweise die Luftblase?","n":6,"info":"Fundus: Kuppel links oberhalb der Kardia unter dem Zwerchfell; enthält meist die Luftblase (Magenblase im Röntgenbild)."},{"d":"d","r":6,"c":14,"a":"PYLORUS","q":"Welcher Schließmuskel reguliert die Magenentleerung ins Duodenum?","n":7,"info":"Pylorus: Magenausgang mit kräftigem Ringmuskel (M. sphincter pyloricus), der die Abgabe des Speisebreis ins Duodenum portioniert."},{"d":"d","r":7,"c":0,"a":"ZAEKUM","q":"Welcher blind endende Dickdarmabschnitt liegt unterhalb der Ileumeinmündung?","n":8,"info":"Zäkum (Blinddarm): Blindsack im rechten Unterbauch unterhalb der Ileumeinmündung; trägt die Appendix vermiformis."}]},{"id":"med-de-16","cat":"med","lang":"de","level":3,"title":"Verdauung III","w":16,"h":14,"x":11,"entries":[{"d":"a","r":1,"c":0,"a":"APPENDIZITIS","q":"Akute Entzündung des Wurmfortsatzes, meist durch Verlegung des Lumens (Kotstein, lymphatische Hyperplasie); häufiger …","n":2,"info":"Appendizitis (Blinddarmentzündung): Schmerz zunächst um den Nabel, wandert in den rechten Unterbauch; Übelkeit, Appetitlosigkeit, leichtes Fieber"},{"d":"a","r":3,"c":2,"a":"NEBENZELLEN","q":"Welche Zellen im Hals der Magendrüsen bilden Schleim?","n":4,"info":"Nebenzellen: Schleimbildende Zellen im Hals der Magendrüsen; ihr Schleim schützt zusammen mit Bikarbonat die Schleimhaut vor Selbstverdauung."},{"d":"a","r":5,"c":6,"a":"ANALFISSUR","q":"Längsriss des Anoderms, meist an der hinteren Kommissur (6 Uhr SSL), ausgelöst durch harten Stuhl","n":6,"info":"Analfissur: Stechender Schmerz beim und nach dem Stuhlgang (oft stundenlang), hellrotes Blut am Papier"},{"d":"a","r":7,"c":6,"a":"CROHN","q":"Morbus …: Chronisch-entzündliche Darmerkrankung mit diskontinuierlichem, transmuralem Befall des gesamten Verdauungstrakts, am …","n":7,"info":"Morbus Crohn: Chronischer, meist unblutiger Durchfall, Bauchschmerz im rechten Unterbauch, Gewichtsverlust, perianale Fisteln"},{"d":"a","r":9,"c":5,"a":"BILIRUBIN","q":"Welches Häm-Abbauprodukt wird nach Glucuronidierung mit der Galle ausgeschieden?","n":8,"info":"Bilirubin (konjugiert): Abbauprodukt des Häms, in der Leber glucuronidiert und mit der Galle ausgeschieden; im Darm entstehen Urobilinogen und Sterkobilin (Stuhlfarbe)."},{"d":"a","r":11,"c":6,"a":"REKTUM","q":"Welcher Darmabschnitt im kleinen Becken speichert den Stuhl vor der Entleerung?","n":9,"info":"Rektum: Ca. 12–15 cm langer Mastdarm im kleinen Becken ohne Tänien und Haustren; speichert den Stuhl in der Ampulla recti."},{"d":"a","r":13,"c":2,"a":"BETAZELLEN","q":"Welche Inselzellen gehen beim Typ-1-Diabetes zugrunde?","n":10,"info":"Beta-Zellen (Insulin): Häufigste Inselzellen; setzen bei steigendem Blutzucker Insulin frei; ihr autoimmuner Untergang führt zum Typ-1-Diabetes."},{"d":"d","r":0,"c":3,"a":"BELEGZELLEN","q":"Welche Zellen der Magendrüsen bilden die Salzsäure?","n":1,"info":"Belegzellen (Parietalzellen): Bilden Salzsäure über die H⁺/K⁺-ATPase (Ziel der Protonenpumpenhemmer) und Intrinsic Factor für die Vitamin-B12-Resorption."},{"d":"d","r":1,"c":0,"a":"AORTENENGE","q":"Welche Engstelle der Speiseröhre entsteht durch Aortenbogen und linken Hauptbronchus?","n":2,"info":"Aortenenge: Mittlere Engstelle, an der Aortenbogen und linker Hauptbronchus die Speiseröhre einengen (etwa Höhe Th4)."},{"d":"d","r":2,"c":14,"a":"ILEUM","q":"Welcher Dünndarmabschnitt besitzt die meisten Peyer-Plaques?","n":3,"info":"Ileum: Distale ca. drei Fünftel des Jejunoileums, eher rechts unten; niedrigere Falten und zahlreiche Peyer-Plaques."},{"d":"d","r":3,"c":7,"a":"ZENTRALVENE","q":"In welches Gefäß im Läppchenzentrum fließt das Sinusoidblut ab?","n":5,"info":"Zentralvene: Zentrum des klassischen Leberläppchens; sammelt das Blut aus den Sinusoiden und führt es zu den Lebervenen."}]},{"id":"med-de-17","cat":"med","lang":"de","level":4,"title":"Verdauung IV","w":17,"h":14,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"DUMPINGSYNDROM","q":"Beschwerden nach Magenresektion oder bariatrischer OP durch zu schnelle Entleerung (hyper-)osmolarer Nahrung in den …","n":1,"info":"Dumping-Syndrom: Früh (bis ca. 30 min): Völle, Krämpfe, Durchfall, Herzrasen, Flush; spät (1–3 h): Unterzuckerung mit Schwitzen, Zittern"},{"d":"a","r":2,"c":1,"a":"LYNCHSYNDROM","q":"Häufigstes erbliches Darmkrebs…: autosomal-dominante Keimbahnmutation in DNA-Mismatch-Reparaturgenen (MLH1, …","n":3,"info":"Lynch-Syndrom (HNPCC): Kolorektales Karzinom in jungem Alter (oft rechtsseitig) ohne Polyposis; familiär gehäuft auch Endometrium-, Ovar-, Magen-, Urothelkarzinome"},{"d":"a","r":4,"c":1,"a":"DISSERAUM","q":"In welchen Spalt ragen die Mikrovilli der Hepatozyten?","n":5,"info":"Disse-Raum: Spalt zwischen Sinusoidendothel und Hepatozyten; hier tauschen die Leberzellen über Mikrovilli Stoffe mit dem Plasma aus."},{"d":"a","r":7,"c":6,"a":"ALPHAZELLEN","q":"Welche Inselzellen schütten bei Unterzuckerung das blutzuckersteigernde Hormon aus?","n":9,"info":"Alpha-Zellen (Glukagon): Bilden Glukagon bei niedrigem Blutzucker; es steigert Glykogenolyse und Glukoneogenese in der Leber."},{"d":"a","r":9,"c":5,"a":"DELTAZELLEN","q":"Welche Inselzellen hemmen parakrin die Hormonfreisetzung ihrer Nachbarzellen?","n":10,"info":"Delta-Zellen (Somatostatin): Bilden Somatostatin, das parakrin die Freisetzung von Insulin und Glukagon hemmt."},{"d":"a","r":11,"c":0,"a":"STAMMZELLE","q":"Aus welchen Zellen geht das gesamte Darmepithel hervor?","n":11,"info":"Stammzelle (Kryptenbasis): LGR5-positive Zellen am Kryptengrund, aus denen alle Epithelzellen hervorgehen; ihre Abkömmlinge wandern zur Zottenspitze und werden abgeschilfert."},{"d":"d","r":0,"c":6,"a":"GASTROPARESE","q":"Verzögerte Magenentleerung ohne mechanisches Hindernis","n":2,"info":"Gastroparese: Übelkeit, Erbrechen unverdauter Speisen Stunden nach dem Essen, frühe Sättigung, Völlegefühl"},{"d":"d","r":2,"c":15,"a":"KRYPTE","q":"In welchen Einsenkungen zwischen den Zotten wird das Darmepithel neu gebildet?","n":4,"info":"Krypte (Lieberkühn): Einsenkung des Epithels zwischen den Zotten; Ort der Zellneubildung – das Darmepithel erneuert sich innerhalb weniger Tage."},{"d":"d","r":4,"c":2,"a":"ILEUS","q":"Unterbrechung der Darmpassage: mechanisch (Verwachsungen, Hernien, Tumoren, Volvulus) oder paralytisch …","n":6,"info":"Ileus (Darmverschluss): Bauchschmerz (kolikartig beim mechanischen), Erbrechen, Stuhl- und Windverhalt, geblähter Bauch"},{"d":"d","r":5,"c":0,"a":"ACHALASIE","q":"Untergang hemmender Neurone im Plexus myentericus: Der untere Ösophagussphinkter erschlafft beim Schlucken nicht, …","n":7,"info":"Achalasie: Dysphagie für feste und flüssige Kost von Beginn an, Regurgitation unverdauter Speisen, Gewichtsverlust, Brustschmerz"},{"d":"d","r":5,"c":12,"a":"DZELLEN","q":"Welche Zellen hemmen über Somatostatin die Säuresekretion im Magen?","n":8,"info":"D-Zellen: Bilden Somatostatin, das parakrin Gastrin- und Säurefreisetzung hemmt (negative Rückkopplung bei niedrigem pH)."}]},{"id":"med-de-18","cat":"med","lang":"de","level":4,"title":"Verdauung V","w":17,"h":18,"x":11,"entries":[{"d":"a","r":1,"c":6,"a":"HEPATOZYTEN","q":"Welche Zellen bilden Albumin und Gerinnungsfaktoren?","n":3,"info":"Hepatozyten: Polygonale Leberzellen (ca. 80 % des Lebervolumens); Stoffwechsel, Entgiftung (Cytochrom P450), Plasmaproteine, Gallebildung."},{"d":"a","r":4,"c":5,"a":"PANETHZELLE","q":"Welche Zellen am Kryptengrund sezernieren Lysozym und Defensine?","n":4,"info":"Paneth-Zelle: Liegen an der Kryptenbasis; bilden antimikrobielle Stoffe (Lysozym, Defensine) und unterstützen die Stammzellnische."},{"d":"a","r":6,"c":0,"a":"GANGEPITHEL","q":"Welche Zellen des Pankreas neutralisieren mit ihrem Sekret die Magensäure im Duodenum?","n":6,"info":"Gangepithel (Bikarbonat): Schaltstück- und Gangzellen sezernieren auf Sekretin hin bikarbonatreiches Sekret (über CFTR) und neutralisieren so den Magensaft."},{"d":"a","r":8,"c":0,"a":"PERIPORTALFELD","q":"Wo liegen Äste von Pfortader, Leberarterie und Gallengang gemeinsam?","n":7,"info":"Periportalfeld (Glisson-Trias): Bindegewebszwickel an den Läppchenecken mit einem Ast der Pfortader, der A. hepatica und einem Gallengang (Trias)."},{"d":"a","r":10,"c":3,"a":"GZELLEN","q":"Welche Zellen setzen Gastrin frei?","n":9,"info":"G-Zellen: Endokrine Zellen im Antrum; schütten auf Eiweiß, Dehnung und Vagusreiz Gastrin aus, das die Säuresekretion steigert."},{"d":"a","r":12,"c":3,"a":"WILSON","q":"Morbus …: Autosomal-rezessive Kupferspeicherkrankheit (ATP7B-Mutation): Kupfer kann nicht über die Galle ausgeschieden werden …","n":11,"info":"Morbus Wilson: Junge Menschen (5–35 J.) mit Lebererkrankung und/oder Tremor, Sprechstörung, Psychose oder Wesensänderung; Kayser-Fleischer-Kornealring."},{"d":"d","r":0,"c":9,"a":"HAUPTZELLEN","q":"Welche Zellen bilden die Vorstufe des eiweißspaltenden Magenenzyms?","n":1,"info":"Hauptzellen: Liegen basal in den Fundus- und Corpusdrüsen und bilden Pepsinogen (wird durch Säure zu Pepsin) sowie Magenlipase."},{"d":"d","r":0,"c":15,"a":"BECHERZELLE","q":"Welche Epithelzellen des Darms bilden Schleim?","n":2,"info":"Becherzelle: Schleimbildende Einzelzellen im Epithel; ihr Muzin schützt die Oberfläche, ihre Zahl nimmt Richtung Dickdarm zu."},{"d":"d","r":5,"c":1,"a":"MAGENKARZINOM","q":"Adenokarzinom des Magens","n":5,"info":"Magenkarzinom: Lange symptomarm; Appetitlosigkeit, Abneigung gegen Fleisch, Gewichtsverlust, Oberbauchschmerz, Anämie"},{"d":"d","r":8,"c":11,"a":"ECLZELLEN","q":"Welche Zellen der Magenschleimhaut setzen Histamin frei?","n":8,"info":"ECL-Zellen: Enterochromaffin-ähnliche Zellen im Corpus; setzen auf Gastrin hin Histamin frei, das über H2-Rezeptoren die Belegzellen stimuliert."},{"d":"d","r":10,"c":4,"a":"ZLINIE","q":"An welcher Grenze wechselt das Epithel von der Speiseröhre zum Magen?","n":10,"info":"Z-Linie: Zickzackförmige Epithelgrenze zum Magen; beim Barrett-Ösophagus verschiebt sie sich nach oben (Zylinderepithel-Metaplasie)."}]},{"id":"med-de-19","cat":"med","lang":"de","level":4,"title":"Verdauung VI","w":16,"h":16,"x":11,"entries":[{"d":"a","r":1,"c":4,"a":"DARMZOTTE","q":"Welche fingerförmigen Schleimhautausstülpungen vergrößern die Dünndarmoberfläche?","n":3,"info":"Darmzotte (Villus): Fingerförmige Schleimhautausstülpung (ca. 0,5–1 mm) mit Epithel, Kapillarnetz und zentralem Chylusgefäß; vergrößert die Oberfläche."},{"d":"a","r":4,"c":0,"a":"KUPFFERZELLEN","q":"Welche Makrophagen sitzen in den Lebersinusoiden?","n":5,"info":"Kupffer-Zellen: Ortsständige Makrophagen in den Sinusoiden; phagozytieren Bakterien und Endotoxine aus dem Pfortaderblut sowie alte Erythrozyten."},{"d":"a","r":6,"c":4,"a":"ASZITES","q":"Freie Flüssigkeit in der Bauchhöhle, zu ca. 80 % durch Leberzirrhose mit portaler Hypertension; seltener maligne …","n":6,"info":"Aszites (inkl. spontan bakterielle Peritonitis): Zunehmender Bauchumfang, Gewichtszunahme, Flankendämpfung, Undulation; bei SBP Fieber, Bauchschmerz oder nur Verschlechterung."},{"d":"a","r":9,"c":1,"a":"AZINUSZELLEN","q":"Welche exokrinen Zellen des Pankreas enthalten Zymogengranula?","n":9,"info":"Azinuszellen (Verdauungsenzyme): Pyramidenförmige Drüsenzellen mit Zymogengranula; sezernieren Enzyme (Trypsinogen, Lipase, Amylase) v. a. auf CCK-Reiz."},{"d":"a","r":12,"c":4,"a":"ANALKARZINOM","q":"Meist Plattenepithelkarzinom von … oder Analrand","n":10,"info":"Analkarzinom: Blutung, Schmerz, Juckreiz, tastbare Verhärtung, Fremdkörpergefühl; oft als Hämorrhoiden verkannt"},{"d":"a","r":14,"c":0,"a":"PPZELLEN","q":"Welche seltenen Inselzellen bilden ein Peptid, das die exokrine Sekretion hemmt?","n":11,"info":"PP-Zellen: Bilden das pankreatische Polypeptid, das die exokrine Pankreassekretion hemmt; v. a. im Pankreaskopf."},{"d":"d","r":0,"c":1,"a":"CHYLUSGEFAESS","q":"Über welches Gefäß der Zotte gelangen Nahrungsfette in den Körper?","n":1,"info":"Chylusgefäß (Lymphkapillare): Zentrales Lymphgefäß der Zotte; nimmt Chylomikronen (Nahrungsfette) auf, die über den Ductus thoracicus an der Leber vorbei ins Blut gelangen."},{"d":"d","r":0,"c":5,"a":"GALLENSAEUREN","q":"Welche aus Cholesterin gebildeten Stoffe emulgieren Nahrungsfette zu Mizellen?","n":2,"info":"Gallensäuren: In der Leber aus Cholesterin gebildet und mit Glycin oder Taurin konjugiert; bilden Mizellen und ermöglichen so die Fettresorption."},{"d":"d","r":3,"c":12,"a":"INVAGINATION","q":"Einstülpung eines Darmabschnitts in den nachfolgenden, meist ileokolisch; typisch bei Kleinkindern (meist …","n":4,"info":"Invagination: Plötzliche Schreiattacken mit angezogenen Beinen, freie Intervalle, Erbrechen, später himbeergeleeartiger Stuhl"},{"d":"d","r":6,"c":7,"a":"ITOZELLEN","q":"Welche Zellen der Leber speichern Vitamin A?","n":7,"info":"Ito-Zellen (Sternzellen): Liegen im Disse-Raum und speichern Vitamin A; aktiviert werden sie zu Myofibroblasten und treiben die Leberfibrose an."},{"d":"d","r":7,"c":14,"a":"SINUSOIDE","q":"Welche Kapillaren mit lückenhaftem Endothel verlaufen zwischen den Leberzellbalken?","n":8,"info":"Sinusoide: Weite Kapillaren mit gefenstertem, lückenhaftem Endothel ohne durchgehende Basalmembran; Mischblut aus Pfortader und Arterie fließt zur Zentralvene."}]},{"id":"med-de-20","cat":"med","lang":"de","level":5,"title":"Verdauung VII","w":14,"h":18,"x":8,"entries":[{"d":"a","r":4,"c":0,"a":"OGILVIESYNDROM","q":"… massive Dilatation des Kolons ohne mechanisches Hindernis, meist bei schwer kranken, frisch operierten oder …","n":4,"info":"Ogilvie-Syndrom (akute Kolonpseudoobstruktion): Rasch zunehmender, trommelartig geblähter Bauch, oft noch Darmgeräusche, wenig Schmerz"},{"d":"a","r":13,"c":4,"a":"INSULINOM","q":"Meist gutartiger, … Tumor der Betazellen des Pankreas; häufigster hormonaktiver neuroendokriner …","n":7,"info":"Insulinom: Whipple-Trias: Unterzuckersymptome (Schwitzen, Zittern, Verwirrtheit) im Nüchternzustand, niedriger Blutzucker, Besserung durch Glukose."},{"d":"a","r":16,"c":0,"a":"LAMBLIASIS","q":"Dünndarminfektion mit dem Protozoon … duodenalis (…), fäkal-oral über Zysten in Wasser oder Nahrung …","n":8,"info":"Lambliasis (Giardiasis): Übelriechende, wässrige bis fettige Durchfälle, Blähungen, Bauchkrämpfe, Gewichtsverlust; oft wochenlang"},{"d":"d","r":0,"c":11,"a":"LEBERABSZESS","q":"Eiteransammlung in der Leber: pyogen (meist über Gallenwege oder Pfortader, z. B. bei Cholangitis, Divertikulitis) …","n":1,"info":"Leberabszess: Fieber, Schüttelfrost, Schmerz im rechten Oberbauch, starkes Krankheitsgefühl."},{"d":"d","r":3,"c":2,"a":"MIRIZZISYNDROM","q":"Eingeklemmter Gallenstein im Gallenblasenhals oder Ductus cysticus, der den Ductus hepaticus communis von außen …","n":2,"info":"Mirizzi-Syndrom: Ikterus zusammen mit Gallenkolik oder Zeichen einer Cholezystitis."},{"d":"d","r":3,"c":5,"a":"HIRSCHSPRUNG","q":"Morbus …: Angeborenes Fehlen von Ganglienzellen (Aganglionose) in den Nervengeflechten des distalen Darms, meist Rektum/Sigma, …","n":3,"info":"Morbus Hirschsprung: Verspäteter Mekoniumabgang (>24–48 h), geblähter Bauch, Erbrechen; später chronische Verstopfung, Gedeihstörung"},{"d":"d","r":4,"c":7,"a":"SIGMAVOLVULUS","q":"Drehung des Sigmas um seine Mesenterialachse mit Darmverschluss und Gefahr der Minderdurchblutung; begünstigt durch …","n":5,"info":"Sigmavolvulus: Massiv aufgeblähter Bauch, Schmerzen, Stuhl- und Windverhalt, spätes Erbrechen"},{"d":"d","r":11,"c":0,"a":"WHIPPLE","q":"Morbus …: Seltene systemische Infektion mit dem grampositiven Aktinobakterium Tropheryma …, v.a. bei Männern mittleren …","n":6,"info":"Morbus Whipple: Gelenkschmerzen (oft Jahre vorher), Durchfall/Fettstühle, Gewichtsverlust, Fieber, Lymphknotenschwellung, ZNS-Symptome"}]},{"id":"med-de-21","cat":"med","lang":"de","level":2,"title":"Niere & Hormone I","w":16,"h":23,"x":11,"entries":[{"d":"a","r":1,"c":4,"a":"HYPOTHYREOSE","q":"Unterfunktion der Schilddrüse mit Mangel an T4/T3; in Deutschland meist durch Hashimoto-Thyreoiditis, außerdem nach …","n":2,"info":"Hypothyreose: Müdigkeit, Kälteempfindlichkeit, Gewichtszunahme, Obstipation, trockene Haut, langsamer Puls, Antriebsarmut, depressive Stimmung"},{"d":"a","r":3,"c":6,"a":"ADIPOSITAS","q":"Übermäßige Fettansammlung mit Gesundheitsrisiko, definiert ab BMI 30 kg/m². Ursachen: Energieüberschuss, …","n":3,"info":"Adipositas: Übergewicht, oft Luftnot bei Belastung, Gelenkbeschwerden, Schnarchen und Schlafapnoe, vermehrtes Schwitzen"},{"d":"a","r":10,"c":2,"a":"VITAMINDMANGEL","q":"Unzureichende Versorgung mit … D, meist durch wenig UV-B-Licht (Winter, Innenaufenthalt, dunkle Haut, …","n":6,"info":"Vitamin-D-Mangel: Oft symptomlos; bei schwerem Mangel Knochenschmerzen, Muskelschwäche, Stürze; Kinder: Rachitis, Erwachsene: Osteomalazie"},{"d":"a","r":12,"c":0,"a":"BLASENDREIECK","q":"Welche faltenfreie Fläche der Blase liegt zwischen Ureteröffnungen und Harnröhrenabgang?","n":8,"info":"Blasendreieck (Trigonum vesicae): Glatte, nicht faltbare Fläche zwischen den beiden Harnleitermündungen und dem Harnröhrenabgang."},{"d":"a","r":14,"c":5,"a":"EISENMANGEL","q":"Häufigster Nährstoffmangel weltweit: negative Eisenbilanz durch Blutverlust (Menstruation, Magen-Darm), erhöhten …","n":9,"info":"Eisenmangel: Müdigkeit, Leistungsminderung, Haarausfall, brüchige Nägel, Mundwinkelrhagaden, Restless Legs; später Anämie mit Blässe"},{"d":"a","r":17,"c":4,"a":"GICHT","q":"Ablagerung von Harnsäurekristallen in Gelenken und Geweben bei chronischer Hyperurikämie, meist durch verminderte …","n":10,"info":"Gicht (Arthritis urica): Akuter, extrem schmerzhafter, geröteter, geschwollener Gelenkanfall, oft nachts, klassisch im Großzehengrundgelenk (Podagra)"},{"d":"a","r":20,"c":3,"a":"NIERENRINDE","q":"In welcher Nierenschicht liegen die Nierenkörperchen?","n":11,"info":"Nierenrinde (Cortex): Äußere Schicht mit Nierenkörperchen, gewundenen Tubuli und Markstrahlen; reicht als Columnae renales zwischen die Pyramiden."},{"d":"d","r":0,"c":10,"a":"HYPOGLYKAEMIE","q":"Zu niedriger Blutzucker (relevant unter ca. 70 mg/dl, schwer unter 54 mg/dl), meist als Nebenwirkung von Insulin …","n":1,"info":"Hypoglykämie: Zittern, Schwitzen, Herzrasen, Heißhunger, Unruhe; dann Verwirrtheit, Wesensänderung, Krampfanfall, Bewusstlosigkeit"},{"d":"d","r":5,"c":0,"a":"PRAEDIABETES","q":"Vorstufe des Typ-2-Diabetes mit erhöhten, aber noch nicht diabetischen …: abnorme Nüchtern… …","n":4,"info":"Prädiabetes (gestörte Glukoseregulation): Keine Symptome; meist Übergewicht, Bauchfett, Bluthochdruck"},{"d":"d","r":9,"c":5,"a":"HARNWEGSINFEKT","q":"Bakterielle Blasenentzündung, meist durch aufsteigende E. coli","n":5,"info":"Harnwegsinfekt (akute Zystitis): Brennen beim Wasserlassen (Dysurie), häufiger Harndrang (Pollakisurie), Unterbauchschmerz, evtl. Blut im Urin; kein Fieber."},{"d":"d","r":10,"c":8,"a":"NIERENSTEINE","q":"Konkremente in Niere und Harnwegen, meist Calciumoxalat","n":7,"info":"Nierensteine (Nephro-/Urolithiasis): Kolik: wellenförmiger, stärkster Flankenschmerz mit Ausstrahlung in Leiste und Genitale, Unruhe, Übelkeit, Blut im Urin."}]},{"id":"med-de-22","cat":"med","lang":"de","level":3,"title":"Niere & Hormone II","w":16,"h":17,"x":11,"entries":[{"d":"a","r":2,"c":2,"a":"CUSHINGSYNDROM","q":"Krankheitsbild durch chronisch erhöhte Glukokortikoide; am häufigsten iatrogen (Kortisontherapie), endogen v. a. …","n":2,"info":"Cushing-Syndrom (Hyperkortisolismus): Stammfettsucht, Vollmondgesicht, Büffelnacken, livide Striae, dünne Haut, Muskelschwäche, Hypertonie, Diabetes, Osteoporose"},{"d":"a","r":5,"c":1,"a":"NIERENBECKEN","q":"Welcher trichterförmige Raum sammelt den Harn aller Kelche?","n":5,"info":"Nierenbecken: Trichterförmiger Sammelraum (Pelvis renalis) im Sinus renalis; geht am Hilus in den Harnleiter über, häufiger Sitz von Nierensteinen."},{"d":"a","r":10,"c":4,"a":"URETHRITIS","q":"Entzündung der Harnröhre, meist sexuell übertragen: gonorrhoisch (Neisseria gonorrhoeae) oder nicht-gonorrhoisch …","n":8,"info":"Urethritis: Brennen beim Wasserlassen, Ausfluss aus der Harnröhre (eitrig bei Gonorrhö, glasig bei Chlamydien); bei Frauen oft symptomlos."},{"d":"a","r":12,"c":0,"a":"BASEDOW","q":"Morbus …: Autoimmunerkrankung mit stimulierenden Antikörpern gegen den TSH-Rezeptor (TRAK), die die Schilddrüse zu …","n":9,"info":"Morbus Basedow (Graves' disease): Merseburger Trias: Struma, Exophthalmus, Tachykardie; dazu Gewichtsverlust, Unruhe, Schwitzen; selten prätibiales Myxödem"},{"d":"a","r":14,"c":3,"a":"DUENNDARM","q":"Wo werden die meisten Nährstoffe resorbiert?","n":10,"info":"Dünndarm (Resorptionsort): Resorbiert Kohlenhydrate als Monosaccharide, Proteine als Aminosäuren und Peptide und Fette über Mizellen; Eisen v. a. im Duodenum."},{"d":"d","r":0,"c":12,"a":"JODMANGEL","q":"Unzureichende Jodzufuhr","n":1,"info":"Jodmangel: Struma, Knoten; in der Schwangerschaft Gefahr für die kindliche Gehirnentwicklung; schwer: Hypothyreose, Kretinismus"},{"d":"d","r":2,"c":5,"a":"HYPERTHYREOSE","q":"Überfunktion der Schilddrüse mit erhöhten freien Schilddrüsenhormonen; häufigste Ursachen Morbus Basedow und …","n":3,"info":"Hyperthyreose: Gewichtsverlust trotz Heißhunger, Herzrasen/Vorhofflimmern, Wärmeintoleranz, Schwitzen, feiner Tremor, Unruhe, Durchfall"},{"d":"d","r":4,"c":3,"a":"LEBER","q":"Welches Organ hält im Fasten über Glykogenolyse und Glukoneogenese den Blutzucker konstant?","n":4,"info":"Leber (Stoffwechselzentrale): Speichert Glykogen und gibt im Fasten Glukose ab (Glykogenolyse, später Glukoneogenese); bildet Ketonkörper, Lipoproteine und Harnstoff."},{"d":"d","r":5,"c":1,"a":"NIERENKAPSEL","q":"Welche straffe Hülle liegt der Niere direkt auf?","n":5,"info":"Nierenkapsel: Straffe bindegewebige Organkapsel (Capsula fibrosa); ihre Dehnung bei Schwellung verursacht Flankenschmerz."},{"d":"d","r":8,"c":9,"a":"HARNBLASE","q":"Welches Hohlorgan speichert den Harn bis zur Entleerung?","n":6,"info":"Harnblase: Muskulöses Speicherorgan hinter der Symphyse; gefüllt steigt sie über die Symphyse auf (suprapubische Punktion möglich)."},{"d":"d","r":9,"c":13,"a":"ISTHMUS","q":"Welche Gewebsbrücke verbindet die beiden Lappen der Schilddrüse?","n":7,"info":"Isthmus: Gewebsbrücke zwischen beiden Lappen vor der 2.–4. Trachealspange; bei der Tracheotomie zu beachten."}]},{"id":"med-de-23","cat":"med","lang":"de","level":3,"title":"Niere & Hormone III","w":21,"h":13,"x":11,"entries":[{"d":"a","r":0,"c":5,"a":"HYPONATRIAEMIE","q":"Natrium im Serum unter 135 mmol/l; häufigste Elektrolytstörung, meist relativer Wasserüberschuss (SIADH, Herz- oder …","n":1,"info":"Hyponatriämie: Leicht: Übelkeit, Kopfschmerz, Konzentrations- und Gangstörung (Stürze); schwer: Verwirrtheit, Erbrechen, Krampfanfälle, Koma"},{"d":"a","r":2,"c":0,"a":"SARKOPENIE","q":"Altersassoziierter, fortschreitender Verlust von Muskelkraft, Muskelmasse und Funktion; begünstigt durch …","n":4,"info":"Sarkopenie: Nachlassende Kraft (z. B. Probleme beim Aufstehen), langsames Gehen, Stürze, Gebrechlichkeit"},{"d":"a","r":5,"c":9,"a":"NIERENKELCHE","q":"Welche becherförmigen Hohlräume fangen den Harn an den Papillen auf?","n":8,"info":"Nierenkelche: Die Calices minores umfassen die Papillen und vereinigen sich zu meist 2–3 Calices majores, die ins Nierenbecken münden."},{"d":"a","r":8,"c":9,"a":"PROLAKTINOM","q":"Gutartiger, … bildender Tumor des Hypophysenvorderlappens; häufigstes hormonaktives Hypophysenadenom","n":9,"info":"Prolaktinom: Frau: Amenorrhö, Galaktorrhö, Infertilität; Mann: Libido- und Potenzverlust; Makroadenom: Kopfschmerz, Gesichtsfeldausfall"},{"d":"a","r":11,"c":3,"a":"SEITENLAPPEN","q":"Welche Teile der Schilddrüse liegen beidseits der Luftröhre?","n":10,"info":"Seitenlappen (Lobus dexter/sinister): Liegen beidseits von Trachea und Kehlkopf und bewegen sich beim Schlucken mit."},{"d":"d","r":0,"c":5,"a":"HYPOKALIAEMIE","q":"Kalium im Serum unter 3,5 mmol/l, meist durch Verluste (Diuretika, Erbrechen, Durchfall, Abführmittel, …","n":1,"info":"Hypokaliämie: Muskelschwäche, Krämpfe, Verstopfung bis Ileus, Polyurie, Herzrhythmusstörungen; schwer: Lähmungen"},{"d":"d","r":0,"c":9,"a":"NIERENPAPILLE","q":"Wo tritt der fertige Harn aus dem Nierengewebe in das Hohlsystem aus?","n":2,"info":"Nierenpapille: Spitze einer Markpyramide; hier münden die Sammelrohre (Area cribrosa) und der Harn tropft in einen Kelch."},{"d":"d","r":1,"c":1,"a":"HARNLEITER","q":"Welcher Schlauch transportiert den Harn vom Nierenbecken zur Blase?","n":3,"info":"Harnleiter (Ureter): Ca. 25–30 cm langer Muskelschlauch, der den Harn peristaltisch zur Blase transportiert; drei Engstellen sind typische Orte für Steine."},{"d":"d","r":2,"c":3,"a":"KOLLOID","q":"Welche Substanz im Follikellumen dient als Hormonspeicher?","n":5,"info":"Kolloid (Thyreoglobulin): Gelartiger Inhalt des Follikellumens; Thyreoglobulin trägt die iodierten Tyrosinreste und dient als Hormonvorrat."},{"d":"d","r":2,"c":7,"a":"NEBENNIERE","q":"Welche Hormondrüse sitzt dem oberen Nierenpol auf?","n":6,"info":"Nebenniere (aufsitzend): Hormondrüse auf dem oberen Nierenpol innerhalb der Gerota-Faszie; die Rinde bildet Steroidhormone, das Mark Adrenalin und Noradrenalin."},{"d":"d","r":2,"c":12,"a":"NIERE","q":"Welches Organ aktiviert Vitamin D durch Hydroxylierung und scheidet den Großteil der Harnsäure aus?","n":7,"info":"Niere (Ausscheidung & Calcitriol): Scheidet ca. zwei Drittel der Harnsäure aus und bildet aktives Vitamin D (Calcitriol) durch 1α-Hydroxylierung."}]},{"id":"med-de-24","cat":"med","lang":"de","level":4,"title":"Niere & Hormone IV","w":19,"h":16,"x":11,"entries":[{"d":"a","r":2,"c":5,"a":"HYPERKALZAEMIE","q":"Erhöhtes Serum-Calcium; meist durch primären Hyperparathyreoidismus (ambulant) oder Tumoren (stationär: Osteolysen, …","n":4,"info":"Hyperkalzämie: Nierensteine, Knochenschmerz, Übelkeit, Verstopfung, Polyurie, Durst, Müdigkeit, Depression, Verwirrtheit"},{"d":"a","r":7,"c":12,"a":"UROTHEL","q":"Welches dehnbare Epithel kleidet Harnleiter und Blase aus?","n":9,"info":"Urothel (Übergangsepithel): Mehrschichtiges Epithel mit großen Deckzellen (Umbrella-Zellen); flacht bei Füllung ab und ist harndicht."},{"d":"a","r":11,"c":0,"a":"ZYSTENNIEREN","q":"Häufigste erbliche Nierenkrankheit (autosomal-dominant, meist PKD1 oder PKD2): zahlreiche wachsende … …","n":10,"info":"Zystennieren (ADPKD): Früher Bluthochdruck, Flankenschmerz, Blut im Urin, Infekte, Steine, tastbar große Nieren; Nierenversagen meist im mittleren Alter."},{"d":"a","r":12,"c":12,"a":"CUSHING","q":"Morbus …: Hypophysäre Form des …: ein ACTH-bildendes Hypophysenadenom (meist Mikroadenom) stimuliert beide …","n":11,"info":"Morbus Cushing: Stammfettsucht, Vollmondgesicht, Büffelnacken, breite livide Striae, proximale Muskelschwäche, Hypertonie, Hämatomneigung"},{"d":"d","r":0,"c":7,"a":"HYPOKALZAEMIE","q":"Erniedrigtes Serum-Calcium, v. a. bei Hypoparathyreoidismus (nach OP), Vitamin-D-Mangel, Niereninsuffizienz, …","n":1,"info":"Hypokalzämie: Kribbeln um den Mund und an den Fingern, Muskelkrämpfe, Tetanie (Pfötchenstellung), Stimmritzenkrampf, Krampfanfälle"},{"d":"d","r":1,"c":5,"a":"CHYLOMIKRONEN","q":"Welche Lipoproteine bringen Nahrungsfette über die Lymphe ins Blut?","n":2,"info":"Chylomikronen: Größte Lipoproteine; transportieren Nahrungsfette vom Darm über Lymphe und Ductus thoracicus ins Blut."},{"d":"d","r":1,"c":12,"a":"GLOMERULUS","q":"In welchem Kapillarknäuel entsteht der Primärharn?","n":3,"info":"Glomerulus: Kapillarknäuel zwischen Vas afferens und Vas efferens; filtriert über gefenstertes Endothel, Basalmembran und Podozyten den Primärharn."},{"d":"d","r":2,"c":14,"a":"ADDISONKRISE","q":"Lebensbedrohlicher … Cortisolmangel bei bekannter oder unerkannter …, ausgelöst durch …","n":5,"info":"Addison-Krise (akute Nebennierenrindeninsuffizienz): Schwere Hypotonie bis Schock, Erbrechen, Bauchschmerz (Pseudoperitonitis), Fieber, Bewusstseinsstörung"},{"d":"d","r":2,"c":16,"a":"MITOCHONDRIUM","q":"In welchem Zellorganell findet die oxidative Phosphorylierung statt?","n":6,"info":"Mitochondrium: Ort von Citratzyklus, β-Oxidation und Atmungskette; erzeugt den Großteil des ATP durch oxidative Phosphorylierung."},{"d":"d","r":4,"c":18,"a":"CZELLEN","q":"Welche Zellen der Schilddrüse bilden Calcitonin?","n":7,"info":"C-Zellen (parafollikulär): Neuroendokrine Zellen zwischen den Follikeln; bilden Calcitonin, das den Calciumspiegel senkt (Tumormarker beim medullären Karzinom)."},{"d":"d","r":5,"c":10,"a":"TSHREZEPTOR","q":"Gegen welche Struktur richten sich die stimulierenden Antikörper beim Morbus Basedow?","n":8,"info":"TSH-Rezeptor: G-Protein-gekoppelter Rezeptor der Thyreozyten; stimulierende Autoantikörper gegen ihn verursachen den Morbus Basedow."}]},{"id":"med-de-25","cat":"med","lang":"de","level":4,"title":"Niere & Hormone V","w":20,"h":16,"x":11,"entries":[{"d":"a","r":4,"c":6,"a":"HYPERKALIAEMIE","q":"Kalium im Serum über ca. 5,0 mmol/l, meist durch verminderte renale Ausscheidung (Niereninsuffizienz, …","n":8,"info":"Hyperkaliämie: Oft symptomarm; Muskelschwäche, Kribbeln, langsamer Puls, plötzliche Rhythmusstörungen bis Kammerflimmern oder Asystolie"},{"d":"a","r":7,"c":0,"a":"HARNSAEURE","q":"Welches Endprodukt des Purinabbaus kristallisiert bei Gicht aus?","n":10,"info":"Harnsäure: Endprodukt des Purinabbaus über die Xanthinoxidase; schwer löslich – übersteigt der Spiegel die Löslichkeit, fallen Uratkristalle aus (Gicht)."},{"d":"a","r":7,"c":14,"a":"LADA","q":"Langsam fortschreitender … des Erwachsenen; anfangs ohne Insulin behandelbar und daher oft als …","n":11,"info":"LADA (Latent Autoimmune Diabetes in Adults): Diabetes im Erwachsenenalter bei eher schlanken Menschen, frühes Versagen der Tablettentherapie"},{"d":"d","r":0,"c":15,"a":"BOWMANKAPSEL","q":"Welche Hülle fängt das glomeruläre Filtrat auf?","n":1,"info":"Bowman-Kapsel: Doppelwandiger Becher um den Glomerulus: inneres Blatt aus Podozyten, äußeres aus Plattenepithel; fängt das Filtrat im Kapselraum auf."},{"d":"d","r":0,"c":17,"a":"AKROMEGALIE","q":"Überproduktion von Wachstumshormon (GH) nach Schluss der Wachstumsfugen, fast immer durch ein GH-bildendes …","n":2,"info":"Akromegalie: Vergrößerung von Händen, Füßen, Nase, Kinn und Zunge, vergröberte Gesichtszüge, Schwitzen, Karpaltunnelsyndrom, Kopfschmerz"},{"d":"d","r":0,"c":19,"a":"SAMMELROHR","q":"Wo bewirkt ADH durch den Einbau von Aquaporinen die Wasserrückresorption?","n":3,"info":"Sammelrohr: Feinregulation von Wasser (ADH über Aquaporin-2) und Na⁺/K⁺ (Aldosteron) – bestimmt die endgültige Harnkonzentration."},{"d":"d","r":1,"c":12,"a":"VITAMINKMANGEL","q":"… an … K mit verminderter Bildung der Gerinnungsfaktoren II, VII, IX, X; bei Neugeborenen, Cholestase, …","n":4,"info":"Vitamin-K-Mangel: Blutungsneigung: Hämatome, Schleimhaut- und Magen-Darm-Blutungen; Neugeborene: Blutungen bis zur Hirnblutung (Vitamin-K-Mangelblutung)"},{"d":"d","r":3,"c":6,"a":"THYREOZYTEN","q":"Welche Zellen nehmen Iodid aus dem Blut auf?","n":5,"info":"Thyreozyten: Follikelepithelzellen; nehmen Iodid über den Na⁺/I⁻-Symporter auf und bilden Thyreoglobulin, aus dem T3 und T4 freigesetzt werden."},{"d":"d","r":3,"c":9,"a":"HENLESCHLEIFE","q":"Welcher Nephronabschnitt ist Angriffsort von Furosemid?","n":6,"info":"Henle-Schleife: U-förmige Schleife ins Mark; der dicke aufsteigende Teil resorbiert NaCl über NKCC2 (Angriffsort der Schleifendiuretika), aber kein Wasser."},{"d":"d","r":4,"c":0,"a":"KACHEXIE","q":"Multifaktorielles Syndrom mit fortschreitendem Muskel- (± Fett-)Verlust, durch Ernährung allein nicht voll …","n":7,"info":"Kachexie (Tumorkachexie): Starker ungewollter Gewichtsverlust, Muskelschwund, Appetitlosigkeit, Erschöpfung, Funktionsverlust"},{"d":"d","r":5,"c":3,"a":"ZINKMANGEL","q":"Zinkunterversorgung durch geringe Zufuhr (phytatreiche Pflanzenkost), Malabsorption (Morbus Crohn, Zöliakie, nach …","n":9,"info":"Zinkmangel: Haarausfall, Wundheilungsstörung, Ausschlag um Körperöffnungen und an Akren, Geschmacksstörung, Infektanfälligkeit, Wachstumsstörung"}]},{"id":"med-de-26","cat":"med","lang":"de","level":5,"title":"Niere & Hormone VI","w":20,"h":16,"x":11,"entries":[{"d":"a","r":1,"c":0,"a":"GAUCHER","q":"Morbus …: Häufigste lysosomale Speicherkrankheit: autosomal-rezessiver Mangel der Glukozerebrosidase","n":2,"info":"Morbus Gaucher: Massive Milzvergrößerung, Lebervergrößerung, Anämie, Thrombozytopenie mit Blutungen, Knochenschmerzen und -infarkte"},{"d":"a","r":3,"c":2,"a":"LUPUSNEPHRITIS","q":"Nierenbeteiligung beim systemischen Lupus erythematodes durch Immunkomplexablagerungen; betrifft einen großen Teil …","n":6,"info":"Lupusnephritis: Proteinurie, Blut im Urin, Ödeme, Hypertonie bei SLE-Zeichen (Gelenkschmerzen, Schmetterlingserythem, Fieber)."},{"d":"a","r":5,"c":10,"a":"MCADMANGEL","q":"Autosomal-rezessiver Defekt der mittelkettigen Acyl-CoA-Dehydrogenase; häufigste Fettsäureoxidationsstörung","n":8,"info":"MCAD-Mangel: Bei Fasten oder Infekt mit Erbrechen: Lethargie, hypoketotische Hypoglykämie, Krampfanfall, Koma; plötzlicher Tod möglich"},{"d":"a","r":9,"c":11,"a":"FABRY","q":"Morbus …: X-chromosomal vererbte lysosomale Speicherkrankheit durch Mangel an α-Galaktosidase A; Globotriaosylceramid (Gb3) …","n":9,"info":"Morbus Fabry: Brennende Schmerzen in Händen und Füßen ab der Kindheit, Angiokeratome, vermindertes Schwitzen, Proteinurie, Herzwandverdickung"},{"d":"a","r":11,"c":8,"a":"SYMPATHIKUS","q":"Welcher Teil des vegetativen Nervensystems fördert die Speicherphase der Blase?","n":10,"info":"Sympathikus (Plexus hypogastricus): Fasern aus dem thorakolumbalen Mark hemmen den Detrusor (β3) und kontrahieren den Blasenhals (α1) – fördern die Speicherphase."},{"d":"a","r":14,"c":8,"a":"MYXOEDEMKOMA","q":"Lebensbedrohliche Dekompensation einer schweren, meist lange unbehandelten Hypothyreose, häufig ausgelöst durch …","n":11,"info":"Myxödemkoma: Bewusstseinsstörung bis Koma, Hypothermie, Bradykardie, Hypoventilation, teigige Schwellung von Gesicht und Haut"},{"d":"d","r":0,"c":6,"a":"UROSEPSIS","q":"Lebensbedrohliche Organdysfunktion durch eine Infektion der Harnwege, meist bei Abflussbehinderung (Stein, Prostata, …","n":1,"info":"Urosepsis: Fieber oder Untertemperatur, Schüttelfrost, Verwirrtheit, schnelle Atmung, Blutdruckabfall; Flanken- oder Unterbauchschmerz."},{"d":"d","r":1,"c":4,"a":"HYPOPHYSITIS","q":"Entzündung der …: primär autoimmun (lymphozytär, oft um eine Schwangerschaft) oder sekundär, heute zunehmend …","n":3,"info":"Hypophysitis: Kopfschmerz, Müdigkeit, Übelkeit, niedriger Blutdruck, ggf. Sehstörungen oder Polyurie"},{"d":"d","r":2,"c":8,"a":"NEPHROBLASTOM","q":"Häufigster bösartiger Nieren… im Kindesalter (meist 1–5 Jahre) aus embryonalem Nierengewebe; teils bei Syndromen …","n":4,"info":"Nephroblastom (Wilms-Tumor): Schmerzlose, tastbare Schwellung im Bauch (oft von Eltern beim Baden bemerkt), evtl. Blut im Urin, Bluthochdruck."},{"d":"d","r":2,"c":12,"a":"VITAMINAMANGEL","q":"… an Retinol bzw","n":5,"info":"Vitamin-A-Mangel: Nachtblindheit, trockene Augen (Xerophthalmie), Bitot-Flecken, Hornhauterweichung; trockene Haut, Infektanfälligkeit"},{"d":"d","r":3,"c":15,"a":"SIADH","q":"Unangemessen hohe ADH-Wirkung trotz niedriger Serumosmolalität → Wasserretention und Verdünnungshyponatriämie bei …","n":7,"info":"SIADH (Syndrom der inadäquaten ADH-Sekretion): Je nach Natriumabfall Übelkeit, Kopfschmerz, Verwirrtheit, Gangunsicherheit und Stürze, Krampfanfälle; keine Ödeme"}]},{"id":"med-de-27","cat":"med","lang":"de","level":3,"title":"Nerven & Psyche I","w":20,"h":13,"x":11,"entries":[{"d":"a","r":1,"c":6,"a":"PANIKSTOERUNG","q":"Angststörung mit wiederkehrenden, unerwarteten Panikattacken und anhaltender Angst vor weiteren Attacken; oft mit …","n":4,"info":"Panikstörung: Plötzliche intensive Angst mit Herzrasen, Atemnot, Brustenge, Schwindel, Zittern, Todesangst; Gipfel innerhalb von Minuten"},{"d":"a","r":5,"c":11,"a":"PARKINSON","q":"Morbus …: Neurodegenerative Erkrankung mit Untergang dopaminerger Neurone der Substantia nigra (α-Synuclein, Lewy-Körperchen); …","n":9,"info":"Morbus Parkinson (idiopathisches Parkinson-Syndrom): Bradykinese plus Rigor und/oder Ruhetremor, oft einseitig beginnend; später Gang- und Haltungsinstabilität"},{"d":"a","r":9,"c":0,"a":"HYPOTHALAMUS","q":"Welche Zwischenhirnregion steuert Körpertemperatur, Hunger und Durst?","n":10,"info":"Hypothalamus: Liegt unter dem Thalamus; steuert Temperatur, Hunger, Durst, Tag-Nacht-Rhythmus und über die Hypophyse das Hormonsystem."},{"d":"a","r":9,"c":14,"a":"DELIR","q":"Akute, schwankende Störung von Aufmerksamkeit, Bewusstsein und Denken infolge einer körperlichen Ursache (Infekt, …","n":11,"info":"Delir (akuter Verwirrtheitszustand): Akut einsetzende Verwirrtheit mit Aufmerksamkeitsstörung, wechselnder Verlauf, Desorientierung, Unruhe oder Apathie, Schlaf-Wach-Umkehr"},{"d":"d","r":0,"c":7,"a":"BASALGANGLIEN","q":"Welche Kerngruppe steuert den Bewegungsstart und ist beim Morbus Parkinson gestört?","n":1,"info":"Basalganglien: Kerngruppe (Striatum, Pallidum, mit Nucleus subthalamicus und Substantia nigra) für Bewegungsauswahl und -start; Dopaminmangel führt zum Parkinson-Syndrom."},{"d":"d","r":0,"c":9,"a":"FIEBERKRAMPF","q":"Krampfanfall bei Kleinkindern (etwa 6 Monate bis 5 Jahre) im Rahmen von …, ohne Infektion des ZNS; häufig, …","n":2,"info":"Fieberkrampf: Generalisierter Krampfanfall bei Fieber, meist nur wenige Minuten, danach Müdigkeit"},{"d":"d","r":1,"c":2,"a":"HIPPOCAMPUS","q":"Welche Struktur ist entscheidend für die Bildung neuer deklarativer Gedächtnisinhalte?","n":3,"info":"Hippocampus: Im medialen Temporallappen; entscheidend für die Bildung neuer deklarativer Gedächtnisinhalte; empfindlich für Sauerstoffmangel."},{"d":"d","r":3,"c":11,"a":"DEPRESSION","q":"Häufige psychische Erkrankung mit anhaltend gedrückter Stimmung, Interessen- und Antriebsverlust über mindestens …","n":5,"info":"Depression (unipolare depressive Störung): Niedergeschlagenheit, Freudlosigkeit, Antriebsmangel; Schlaf- und Appetitstörung, Schuldgefühle, Suizidgedanken"},{"d":"d","r":4,"c":0,"a":"KLEINHIRN","q":"Welcher Hirnteil in der hinteren Schädelgrube koordiniert Bewegungen und Gleichgewicht?","n":6,"info":"Kleinhirn: Liegt in der hinteren Schädelgrube; koordiniert Bewegungen, Gleichgewicht und Feinmotorik; Schäden verursachen eine gleichseitige Ataxie."},{"d":"d","r":4,"c":4,"a":"HIRNSTAMM","q":"Welcher Hirnabschnitt enthält Atem- und Kreislaufzentrum?","n":7,"info":"Hirnstamm: Mittelhirn, Brücke und Medulla oblongata; enthält die Kerne der Hirnnerven III–XII, Atem- und Kreislaufzentren und die Formatio reticularis."},{"d":"d","r":4,"c":15,"a":"MIGRAENE","q":"Häufige primäre Kopfschmerzerkrankung mit wiederkehrenden Attacken durch erhöhte neuronale Erregbarkeit und …","n":8,"info":"Migräne: Pulsierender, oft einseitiger Kopfschmerz (4–72 h), Übelkeit, Licht- und Lärmempfindlichkeit; bei manchen Aura"}]},{"id":"med-de-28","cat":"med","lang":"de","level":3,"title":"Nerven & Psyche II","w":22,"h":15,"x":11,"entries":[{"d":"a","r":0,"c":4,"a":"FRONTALLAPPEN","q":"In welchem Lappen liegt der primär motorische Kortex?","n":1,"info":"Frontallappen: Größter Lappen vor dem Sulcus centralis; enthält den primär motorischen Kortex (Gyrus praecentralis) und meist links das Broca-Areal."},{"d":"a","r":3,"c":0,"a":"BALKEN","q":"Welche Faserplatte verbindet die beiden Großhirnhälften?","n":5,"info":"Balken (Corpus callosum): Größte Kommissur: verbindet linke und rechte Großhirnhälfte mit rund 200 Mio. Axonen."},{"d":"a","r":3,"c":8,"a":"PARIETALLAPPEN","q":"In welchem Lappen liegt der Gyrus postcentralis?","n":6,"info":"Parietallappen: Hinter dem Sulcus centralis; enthält den primär somatosensorischen Kortex (Gyrus postcentralis) und dient räumlicher Orientierung und Aufmerksamkeit."},{"d":"a","r":5,"c":0,"a":"SCHIZOPHRENIE","q":"Schwere psychische Erkrankung mit Störungen von Denken, Wahrnehmung und Ich-Erleben","n":8,"info":"Schizophrenie: Positiv: Wahn, Stimmenhören, Ich-Störungen; negativ: Antriebs- und Affektverarmung, sozialer Rückzug; kognitive Defizite"},{"d":"a","r":8,"c":10,"a":"THALAMUS","q":"Wo werden fast alle sensiblen und sensorischen Bahnen vor der Großhirnrinde umgeschaltet?","n":10,"info":"Thalamus: Größter Teil des Zwischenhirns, „Tor zum Bewusstsein“: Fast alle sensiblen und sensorischen Bahnen (außer der Riechbahn) werden hier zur Rinde umgeschaltet."},{"d":"d","r":0,"c":8,"a":"TEMPORALLAPPEN","q":"In welchem Lappen liegt die primäre Hörrinde?","n":2,"info":"Temporallappen: Seitlich unter der Fissura lateralis; enthält die primäre Hörrinde (Heschl-Querwindungen), das Wernicke-Areal und mediale Gedächtnisstrukturen."},{"d":"d","r":2,"c":5,"a":"INSOMNIE","q":"Ein- oder … bzw. nicht erholsamer Schlaf mit Beeinträchtigung am Tag; oft durch Stress, Grübeln und …","n":3,"info":"Insomnie (Ein- und Durchschlafstörung): Lange Einschlafzeit, häufiges nächtliches Erwachen, frühes Erwachen; Tagesmüdigkeit, Konzentrationsstörung"},{"d":"d","r":2,"c":10,"a":"GRENZSTRANG","q":"Welche Ganglienkette verläuft beidseits neben der Wirbelsäule?","n":4,"info":"Grenzstrang (Truncus sympathicus): Kette sympathischer Ganglien beidseits der Wirbelsäule; hier werden viele präganglionäre Fasern umgeschaltet."},{"d":"d","r":3,"c":14,"a":"AMYGDALA","q":"Welcher Kern im Temporallappen verarbeitet vor allem Angst und Bedrohung?","n":7,"info":"Amygdala: Mandelkern vor dem Hippocampus; bewertet Reize emotional, v. a. Angst und Bedrohung, und koppelt sie an Gedächtnis und vegetative Reaktionen."},{"d":"d","r":5,"c":0,"a":"SEITENHORN","q":"Wo liegen die Zellkörper der präganglionären sympathischen Neurone?","n":8,"info":"Seitenhorn: Vor allem in Th1–L2 ausgebildet; enthält die präganglionären Neurone des Sympathikus."},{"d":"d","r":5,"c":2,"a":"HINTERHORN","q":"In welchem Teil der grauen Substanz werden Schmerzfasern auf das zweite Neuron umgeschaltet?","n":9,"info":"Hinterhorn: Dorsale graue Substanz; hier werden sensible Afferenzen, v. a. für Schmerz und Temperatur, auf das zweite Neuron umgeschaltet."}]},{"id":"med-de-29","cat":"med","lang":"de","level":3,"title":"Nerven & Psyche III","w":16,"h":19,"x":11,"entries":[{"d":"a","r":1,"c":1,"a":"VORDERWURZEL","q":"Über welche Wurzel verlassen motorische Fasern das Rückenmark?","n":2,"info":"Vorderwurzel: Führt efferente motorische (und vegetative) Fasern aus dem Rückenmark; vereinigt sich mit der Hinterwurzel zum Spinalnerv."},{"d":"a","r":3,"c":6,"a":"DENDRITEN","q":"Über welche Fortsätze empfängt ein Neuron die meisten Eingangssignale?","n":4,"info":"Dendriten: Verzweigte Fortsätze, die über Synapsen Signale empfangen und zum Soma leiten; Dornen (Spines) vergrößern die Kontaktfläche."},{"d":"a","r":5,"c":0,"a":"ZWANGSSTOERUNG","q":"Psychische Störung mit wiederkehrenden aufdringlichen Gedanken (…) und/oder ritualisierten Handlungen …","n":6,"info":"Zwangsstörung: Kontroll-, Wasch-, Ordnungs- oder Zählzwänge, quälende Gedanken (z.B. jemandem zu schaden); hoher Zeitaufwand"},{"d":"a","r":7,"c":1,"a":"HIRNMETASTASEN","q":"Absiedlungen bösartiger Tumoren ins Gehirn – häufigste Hirntumoren bei Erwachsenen","n":7,"info":"Hirnmetastasen: Kopfschmerz, Übelkeit, epileptische Anfälle, fokale Ausfälle, Wesensänderung bei (bekanntem) Tumorleiden"},{"d":"a","r":10,"c":5,"a":"GLIOBLASTOM","q":"Häufigster und bösartigster primärer Hirntumor bei Erwachsenen (astrozytär, WHO-Grad 4, IDH-Wildtyp), meist ab dem …","n":11,"info":"Glioblastom: Rasch zunehmende Kopfschmerzen, Wesensänderung, neu aufgetretene epileptische Anfälle, fokale Ausfälle"},{"d":"d","r":0,"c":4,"a":"ADHS","q":"Neuroentwicklungsstörung mit Un…, … und Impulsivität, die in der Kindheit beginnt und oft …","n":1,"info":"ADHS (Aufmerksamkeitsdefizit-/Hyperaktivitätsstörung): Ablenkbarkeit, Vergesslichkeit, motorische Unruhe, Ungeduld, impulsives Handeln in mehreren Lebensbereichen"},{"d":"d","r":1,"c":11,"a":"EPIDURALRAUM","q":"In welchen Raum wird bei der Periduralanästhesie das Lokalanästhetikum gespritzt?","n":3,"info":"Epiduralraum: Fett- und venenreicher Raum zwischen Dura mater und Wirbelkanalwand; hier wird bei der Periduralanästhesie das Lokalanästhetikum injiziert."},{"d":"d","r":4,"c":2,"a":"RADIALISPARESE","q":"Schädigung des N. …, typischerweise am Oberarm durch Druck im Schlaf (Parkbanklähmung) oder bei einer …","n":5,"info":"Radialisparese: Fallhand: Handgelenk und Finger können nicht gestreckt werden, Taubheit am Handrücken zwischen Daumen und Zeigefinger"},{"d":"d","r":7,"c":6,"a":"EPILEPSIE","q":"Neigung zu wiederholten, nicht provozierten Anfällen durch synchrone Entladungen von Nervenzellverbänden","n":8,"info":"Epilepsie: Anfälle: z.B. Bewusstseinsverlust mit tonisch-klonischen Zuckungen, seitlichem Zungenbiss, Einnässen; fokale Anfälle mit Automatismen"},{"d":"d","r":9,"c":8,"a":"VORDERHORN","q":"Wo liegen die Zellkörper der α-Motoneurone?","n":9,"info":"Vorderhorn: Ventrale graue Substanz mit α- und γ-Motoneuronen, deren Axone über die Vorderwurzel zu den Skelettmuskeln ziehen."},{"d":"d","r":9,"c":14,"a":"SOMA","q":"In welchem Teil des Neurons liegen Kern und Nissl-Schollen?","n":10,"info":"Soma (Zellkörper): Zellkörper mit Kern und Nissl-Schollen (raues ER); hier wird der Großteil der Proteine des Neurons synthetisiert."}]},{"id":"med-de-30","cat":"med","lang":"de","level":4,"title":"Nerven & Psyche IV","w":17,"h":19,"x":11,"entries":[{"d":"a","r":0,"c":7,"a":"BOTULISMUS","q":"Lähmung durch … von Clostridium …, das die Acetylcholinfreisetzung an der motorischen Endplatte …","n":1,"info":"Botulismus: Absteigende symmetrische Lähmung: Doppelbilder, Ptosis, weite Pupillen, Schluck- und Sprechstörung, Mundtrockenheit, dann Atemlähmung"},{"d":"a","r":4,"c":0,"a":"AXONHUEGEL","q":"Wo wird im Neuron normalerweise das Aktionspotenzial ausgelöst?","n":3,"info":"Axonhügel: Ursprungskegel des Axons ohne Nissl-Schollen; mit dem Initialsegment höchste Dichte spannungsgesteuerter Na⁺-Kanäle – hier startet das Aktionspotenzial."},{"d":"a","r":4,"c":13,"a":"AXON","q":"Welcher Fortsatz leitet Aktionspotenziale vom Zellkörper weg?","n":5,"info":"Axon: Einzelner, oft langer Fortsatz, der Aktionspotenziale vom Soma zu den Synapsen leitet; Stofftransport entlang von Mikrotubuli."},{"d":"a","r":6,"c":1,"a":"PYRAMIDENBAHN","q":"Welche Bahn leitet die Willkürmotorik von der Hirnrinde zum Rückenmark?","n":6,"info":"Pyramidenbahn (Tractus corticospinalis): Absteigende Bahn der Willkürmotorik; die meisten Fasern kreuzen in der Pyramidenkreuzung der Medulla oblongata und laufen im Seitenstrang."},{"d":"a","r":8,"c":1,"a":"MYELINSCHEIDE","q":"Welche lipidreiche Hülle beschleunigt die Erregungsleitung entlang des Axons?","n":7,"info":"Myelinscheide: Lipidreiche Hülle aus Oligodendrozyten (ZNS) bzw. Schwann-Zellen (PNS); isoliert das Axon und beschleunigt die Erregungsleitung."},{"d":"a","r":11,"c":5,"a":"GLIAZELLEN","q":"Welche Nicht-Nervenzellen stützen, isolieren und schützen die Neurone im ZNS?","n":9,"info":"Gliazellen (Astrozyt, Oligodendrozyt, Mikroglia): Astrozyten bilden mit ihren Endfüßen einen Teil der Blut-Hirn-Schranke und puffern K⁺, Oligodendrozyten myelinisieren, Mikroglia sind die Immunzellen des ZNS."},{"d":"a","r":13,"c":1,"a":"POLIOMYELITIS","q":"Infektion mit dem Poliovirus (fäkal-oral), das bei einem kleinen Teil der Infizierten die motorischen …","n":10,"info":"Poliomyelitis (Kinderlähmung): Nach Fieber und Infekt plötzlich asymmetrische schlaffe Lähmungen ohne Gefühlsstörung"},{"d":"a","r":18,"c":3,"a":"DERMATOM","q":"Wie heißt das Hautareal, das ein einzelnes Rückenmarkssegment sensibel versorgt?","n":11,"info":"Dermatom: Hautareal, das ein Spinalnervensegment sensibel versorgt, z. B. C6 Daumen, Th10 Nabel, L5 Großzehe."},{"d":"d","r":0,"c":13,"a":"SCHWANNZELLE","q":"Welche Zellen bilden im peripheren Nervensystem das Myelin?","n":2,"info":"Schwann-Zelle: Gliazelle des PNS; myelinisiert je ein Axonsegment und leitet die Regeneration durchtrennter Nerven (Büngner-Bänder)."},{"d":"d","r":4,"c":3,"a":"NERVENHUELLEN","q":"Welche Bindegewebsschichten umhüllen Nervenfasern, Faszikel und den gesamten Nerv?","n":4,"info":"Nervenhüllen (Endo-, Peri-, Epineurium): Endoneurium umgibt jede Faser, Perineurium (Diffusionsbarriere) jeden Faszikel, Epineurium den ganzen Nerv."},{"d":"d","r":10,"c":10,"a":"MENINGEOM","q":"Meist gutartiger, langsam wachsender Tumor der Hirnhäute (Arachnoidalzellen); häufigster primärer intrakranieller …","n":8,"info":"Meningeom: Oft Zufallsbefund; je nach Lage Kopfschmerz, Anfälle, Wesensänderung, Riech- oder Sehstörung"}]},{"id":"med-de-31","cat":"med","lang":"de","level":3,"title":"Bewegung, Haut & Fortpflanzung I","w":18,"h":15,"x":11,"entries":[{"d":"a","r":0,"c":9,"a":"EPIDERMIS","q":"Welche gefäßfreie Hautschicht besteht aus verhorntem Plattenepithel?","n":4,"info":"Epidermis: Oberhaut aus mehrschichtigem verhorntem Plattenepithel, gefäßfrei; erneuert sich in ca. 4 Wochen."},{"d":"a","r":2,"c":0,"a":"DERMATOMYKOSEN","q":"Oberflächliche Pilzinfektionen von Haut, Haaren und Nägeln durch … (v. a. Trichophyton rubrum); sehr …","n":6,"info":"Dermatomykosen (Tinea, z. B. Fußpilz): Juckende, schuppende Rötung mit randbetonter Ausbreitung; zwischen den Zehen Mazeration; Nagelbefall: verdickte, gelbliche, brüchige Nägel"},{"d":"a","r":5,"c":10,"a":"ARTHROSE","q":"Häufigste Gelenkerkrankung: fortschreitender Knorpelverlust mit Umbau des Knochens, v. a. Knie, Hüfte, Fingergelenke","n":9,"info":"Arthrose (Gon-/Koxarthrose): Belastungs- und Anlaufschmerz, kurze Morgensteifigkeit (< 30 min), Bewegungseinschränkung, Krepitation"},{"d":"a","r":10,"c":0,"a":"FASZIE","q":"Welche Bindegewebshülle bildet die Muskellogen?","n":10,"info":"Faszie: Bindegewebshülle um Muskeln und Muskelgruppen; bildet Logen – ein Druckanstieg darin führt zum Kompartmentsyndrom."},{"d":"a","r":14,"c":0,"a":"DERMIS","q":"Welche Hautschicht verleiht der Haut ihre Reißfestigkeit?","n":11,"info":"Dermis (Lederhaut): Bindegewebsschicht mit Papillarschicht (Kapillaren, Tastkörperchen) und Geflechtschicht (Kollagen, Reißfestigkeit)."},{"d":"d","r":0,"c":0,"a":"HYDROZELE","q":"Flüssigkeitsansammlung zwischen den Hüllen des Hodens (Tunica vaginalis); angeboren bei offenem Processus vaginalis …","n":1,"info":"Hydrozele (Wasserbruch): Schmerzlose, prallelastische, glatte Schwellung des Hodensacks"},{"d":"d","r":0,"c":5,"a":"OSTEOPOROSE","q":"Systemische Skeletterkrankung mit verminderter Knochenmasse und gestörter Mikroarchitektur → erhöhtes Frakturrisiko","n":2,"info":"Osteoporose: Lange stumm; Frakturen bei Bagatelltrauma (Wirbelkörper, Schenkelhals, Radius), Größenverlust, Rundrücken, Rückenschmerz"},{"d":"d","r":0,"c":7,"a":"SAMENLEITER","q":"Welcher Gang wird bei der Vasektomie durchtrennt?","n":3,"info":"Samenleiter (Ductus deferens): Muskulöser Gang vom Nebenhoden durch den Leistenkanal zur Prostata; wird bei der Vasektomie durchtrennt."},{"d":"d","r":0,"c":10,"a":"PSORIASIS","q":"Chronisch-entzündliche, immunvermittelte Systemerkrankung mit beschleunigter Keratinozytenproliferation …","n":5,"info":"Psoriasis (Schuppenflechte): Scharf begrenzte, gerötete Plaques mit silbrig-weißer Schuppung an Streckseiten, Kopfhaut, Sakralregion; Nagelveränderungen"},{"d":"d","r":2,"c":3,"a":"MAMMAKARZINOM","q":"Häufigste Krebserkrankung der Frau: bösartiger Tumor der Brustdrüse (meist invasiv, Typ NST); Risiko: Alter, …","n":7,"info":"Mammakarzinom (Brustkrebs): Tastbarer, derber, schlecht verschieblicher Knoten, Hauteinziehung, Orangenhaut, Mamillenretraktion oder -sekretion, axilläre Lymphknoten"},{"d":"d","r":3,"c":15,"a":"PROSTATA","q":"Welche Drüse kann bei der rektalen Untersuchung getastet werden?","n":8,"info":"Prostata: Kastaniengroße Drüse unter der Blase um die Harnröhre; vom Rektum aus tastbar, liefert einen Teil des Ejakulats (u. a. PSA)."}]},{"id":"med-de-32","cat":"med","lang":"de","level":3,"title":"Bewegung, Haut & Fortpflanzung II","w":18,"h":14,"x":11,"entries":[{"d":"a","r":0,"c":3,"a":"DEKUBITUS","q":"Lokale Schädigung von Haut und darunterliegendem Gewebe durch anhaltenden Druck und Scherkräfte, meist über …","n":1,"info":"Dekubitus (Druckgeschwür): Nicht wegdrückbare Rötung bis zu tiefen Ulzera mit Nekrosen über Knochenvorsprüngen bei bettlägerigen oder sitzenden Patienten"},{"d":"a","r":3,"c":0,"a":"EILEITER","q":"In welchem Organ findet die Befruchtung meist statt?","n":4,"info":"Eileiter (Tuba uterina): Ca. 10–15 cm lang mit Infundibulum (Fimbrien), Ampulle und Isthmus; transportiert die Eizelle und ist Ort der Befruchtung."},{"d":"a","r":7,"c":4,"a":"ZERVIXKARZINOM","q":"Bösartiger Tumor des …, fast immer durch persistierende Infektion mit Hochrisiko-HPV (v. a. Typ …","n":7,"info":"Zervixkarzinom (Gebärmutterhalskrebs): Früh symptomlos; später Kontaktblutung (nach Geschlechtsverkehr), Zwischenblutungen, fleischwasserfarbener Ausfluss; spät Schmerz, Harnstau"},{"d":"a","r":9,"c":8,"a":"PERIOST","q":"Welche schmerzempfindliche Hülle umgibt den Knochen außen?","n":8,"info":"Periost (Knochenhaut): Gefäß- und nervenreiche Hülle mit knochenbildender Schicht; Ort des Dickenwachstums und der Frakturheilung, sehr schmerzempfindlich."},{"d":"a","r":10,"c":2,"a":"HODEN","q":"In welchem Organ werden die Spermien gebildet?","n":9,"info":"Hoden (Testis): Pflaumenförmig im Skrotum, umhüllt von der derben Tunica albuginea; in seinen Läppchen liegen die Samenkanälchen."},{"d":"a","r":11,"c":10,"a":"NAGEL","q":"Welche verhornte Platte entsteht aus einer Matrix an Finger- und Zehenenden?","n":10,"info":"Nagel: Verhornte Platte aus der Nagelmatrix; Fingernägel wachsen ca. 0,1 mm pro Tag."},{"d":"d","r":0,"c":5,"a":"KONTAKTEKZEM","q":"Ekzem durch Haut…: … (Barriereschädigung, z. B. Feuchtarbeit, Seifen) oder … …","n":2,"info":"Kontaktekzem (allergisch/irritativ): Juckende, gerötete, schuppende, ggf. bläschenbildende Herde am Kontaktort (Hände, Ohrläppchen, Bauchnabel)"},{"d":"d","r":0,"c":10,"a":"UTERUS","q":"In welchem Organ nistet sich die befruchtete Eizelle ein?","n":3,"info":"Uterus (Gebärmutter): Birnenförmiges muskuläres Hohlorgan mit Fundus, Corpus und Cervix; normalerweise anteversiert und anteflektiert."},{"d":"d","r":3,"c":0,"a":"ERYSIPEL","q":"Akute bakterielle Infektion der oberen Dermis und der Lymphspalten, meist durch β-hämolysierende Streptokokken der …","n":4,"info":"Erysipel (Wundrose): Scharf begrenzte, flammenförmige, überwärmte Rötung, meist am Unterschenkel, mit Fieber und Schüttelfrost"},{"d":"d","r":6,"c":8,"a":"DIAPHYSE","q":"Wie heißt der Schaft eines Röhrenknochens?","n":5,"info":"Diaphyse: Schaft der Röhrenknochen aus kompaktem Knochen um die Markhöhle."},{"d":"d","r":6,"c":11,"a":"VAGINA","q":"Welches Organ besitzt durch Laktobazillen ein saures Milieu?","n":6,"info":"Vagina: Muskulöser Schlauch mit unverhorntem Plattenepithel; ein saures Milieu durch Laktobazillen (Döderlein) schützt vor Infektionen."}]},{"id":"med-de-33","cat":"med","lang":"de","level":3,"title":"Bewegung, Haut & Fortpflanzung III","w":19,"h":14,"x":11,"entries":[{"d":"a","r":0,"c":3,"a":"BRUSTDRUESE","q":"Welche Drüse bildet nach der Geburt die Milch?","n":1,"info":"Brustdrüse (Glandula mammaria): 15–20 Drüsenlappen, deren Milchgänge an der Mamille münden; eingebettet in Fettgewebe auf der Pektoralisfaszie."},{"d":"a","r":2,"c":6,"a":"HAARFOLLIKEL","q":"Aus welcher Struktur wächst ein Haar?","n":3,"info":"Haarfollikel: Epidermale Einsenkung mit Haarzwiebel und Papille; dazu gehören Talgdrüse und M. arrector pili (Gänsehaut)."},{"d":"a","r":4,"c":5,"a":"HERZMUSKULATUR","q":"Welche Muskelart ist quergestreift, aber nicht willkürlich steuerbar?","n":5,"info":"Herzmuskulatur: Quergestreift, aber unwillkürlich; verzweigte Zellen mit Glanzstreifen, erregt durch ein eigenes Schrittmachersystem."},{"d":"a","r":8,"c":9,"a":"SKABIES","q":"Ansteckender Hautbefall durch die Milbe Sarcoptes scabiei, die Gänge in der Hornschicht gräbt","n":8,"info":"Skabies (Krätze): Starker, nachts betonter Juckreiz; Milbengänge und Papeln an Fingerzwischenräumen, Handgelenken, Achseln, Genitale, Brustwarzen"},{"d":"a","r":9,"c":0,"a":"PHIMOSE","q":"Verengung der …, die sich nicht über die Eichel zurückziehen lässt; bis ins Schulalter oft physiologisch, …","n":9,"info":"Phimose (Vorhautverengung): Vorhaut nicht zurückziehbar, Ballonieren beim Wasserlassen, wiederkehrende Entzündungen (Balanoposthitis), Schmerzen bei Erektion"},{"d":"a","r":11,"c":5,"a":"SPONGIOSA","q":"Welche bälkchenartige Knochenstruktur folgt den Belastungslinien?","n":10,"info":"Spongiosa: Schwammartiges Netz aus Knochenbälkchen entlang der Belastungslinien (Trajektorien); zwischen den Bälkchen liegt Knochenmark."},{"d":"a","r":13,"c":4,"a":"WIRBEL","q":"Welcher Knochen besteht aus Körper, Bogen und Fortsätzen und umschließt das Rückenmark?","n":11,"info":"Wirbel: Wirbelkörper (trägt die Last), Wirbelbogen (umschließt das Wirbelloch) sowie Dorn- und Querfortsätze als Muskelansätze."},{"d":"d","r":0,"c":6,"a":"SCHWELLKOERPER","q":"Welche Bluträume im Penis füllen sich bei der Erektion?","n":2,"info":"Schwellkörper (Corpora cavernosa & spongiosum): Bluträume im Penis; die Erektion entsteht durch parasympathisch vermittelte NO-Freisetzung und Gefäßerweiterung."},{"d":"d","r":3,"c":3,"a":"SKROTUM","q":"Welcher Hautsack reguliert über Muskeln die Hodentemperatur?","n":4,"info":"Skrotum: Hautsack mit M. dartos und M. cremaster, die die Hodentemperatur unter der Körpertemperatur halten."},{"d":"d","r":4,"c":10,"a":"URTIKARIA","q":"Flüchtige Quaddeln und/oder Angioödeme durch Mastzellaktivierung mit Histaminfreisetzung; akut (< 6 Wochen, oft …","n":6,"info":"Urtikaria (Nesselsucht): Juckende Quaddeln, die einzeln innerhalb von 24 h verschwinden; ggf. tiefe Schwellungen von Lippen und Lidern (Angioödem)"},{"d":"d","r":7,"c":1,"a":"SEHNE","q":"Welche Struktur überträgt die Kraft vom Muskel auf den Knochen?","n":7,"info":"Sehne: Straffes parallelfaseriges Bindegewebe (Kollagen Typ I); überträgt die Muskelkraft auf den Knochen, Golgi-Organe messen ihre Spannung."}]},{"id":"med-de-34","cat":"med","lang":"de","level":3,"title":"Bewegung, Haut & Fortpflanzung IV","w":21,"h":13,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"NEBENHODEN","q":"Wo reifen und lagern die Spermien nach ihrer Bildung?","n":1,"info":"Nebenhoden (Epididymis): Liegt dem Hoden hinten an; hier reifen die Spermien, erlangen ihre Beweglichkeit und werden gespeichert."},{"d":"a","r":2,"c":17,"a":"OVAR","q":"Welches Organ enthält die Follikel und bildet Östrogene?","n":7,"info":"Ovar (Eierstock): Mandelförmig an der Beckenwand; Rinde mit Follikeln, Mark mit Gefäßen; bildet Östrogene und Progesteron."},{"d":"a","r":3,"c":2,"a":"DOUGLASRAUM","q":"Wo sammelt sich bei der Frau freie Flüssigkeit in der Bauchhöhle zuerst?","n":8,"info":"Douglas-Raum (Excavatio rectouterina): Tiefster Punkt der weiblichen Bauchhöhle zwischen Uterus und Rektum; hier sammelt sich freie Flüssigkeit zuerst."},{"d":"a","r":5,"c":9,"a":"SAMENSTRANG","q":"Welcher Strang zieht durch den Leistenkanal zum Hoden?","n":9,"info":"Samenstrang (Funiculus spermaticus): Strang im Leistenkanal mit Ductus deferens, A. testicularis, Plexus pampiniformis und Nerven."},{"d":"d","r":0,"c":2,"a":"BANDSCHEIBE","q":"Welche Struktur zwischen zwei Wirbelkörpern federt Stöße ab?","n":2,"info":"Bandscheibe (Discus intervertebralis): Faserring (Anulus fibrosus) um einen Gallertkern (Nucleus pulposus); Vorfälle meist nach dorsolateral, v. a. bei L4/5 und L5/S1."},{"d":"d","r":1,"c":17,"a":"KOMPAKTA","q":"Welche dichte Knochenschicht bildet die Wand des Röhrenknochenschafts?","n":3,"info":"Kompakta (Substantia compacta): Dichte äußere Rindenschicht, besonders dick im Schaft; trägt den Großteil der Biegebelastung."},{"d":"d","r":2,"c":4,"a":"SUBKUTIS","q":"Welche Hautschicht besteht vorwiegend aus Fettgewebe?","n":4,"info":"Subkutis: Unterhaut aus lockerem Binde- und Fettgewebe; isoliert, speichert Energie und dient als Polster."},{"d":"d","r":2,"c":7,"a":"TALGDRUESE","q":"Welche holokrine Drüse mündet in den Haarfollikel?","n":5,"info":"Talgdrüse: Holokrine Drüse, meist am Haarfollikel; ihr Sebum fettet Haut und Haare, die Bildung ist androgenabhängig (Akne)."},{"d":"d","r":2,"c":9,"a":"PROSTATITIS","q":"Entzündung der …: akut bakteriell (meist E. coli), chronisch bakteriell oder – am häufigsten – chronisches …","n":6,"info":"Prostatitis: Akut: Fieber, Schüttelfrost, Dysurie, Damm- und Unterbauchschmerz, Harnverhalt; chronisch: Beckenschmerz, Miktions-/Ejakulationsbeschwerden"},{"d":"d","r":5,"c":12,"a":"EPIPHYSE","q":"Welcher Abschnitt eines Röhrenknochens trägt die Gelenkfläche?","n":10,"info":"Epiphyse: Gelenknahes Endstück aus Spongiosa, überzogen von hyalinem Gelenkknorpel."},{"d":"d","r":5,"c":14,"a":"SKOLIOSE","q":"Dreidimensionale Verkrümmung der Wirbelsäule mit seitlicher Abweichung und Rotation der Wirbel; meist idiopathisch …","n":11,"info":"Skoliose: Asymmetrie von Schultern, Taille und Becken, Rippenbuckel beim Vorbeugen; meist schmerzlos"}]},{"id":"med-de-35","cat":"med","lang":"de","level":3,"title":"Bewegung, Haut & Fortpflanzung V","w":20,"h":15,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"MUSKELKRAEMPFE","q":"Plötzliche, unwillkürliche, schmerzhafte Kontraktionen eines …, meist nachts in der Wade; meist idiopathisch, …","n":1,"info":"Muskelkrämpfe (Wadenkrämpfe): Akut einsetzender, sehr schmerzhafter, tastbar verhärteter Muskel für Sekunden bis Minuten, Besserung durch Dehnung"},{"d":"a","r":3,"c":0,"a":"GELENKKNORPEL","q":"Welches gefäßfreie Gewebe überzieht die Gelenkflächen?","n":6,"info":"Gelenkknorpel: Hyaliner Knorpel ohne Gefäße und Nerven; wird über die Synovia ernährt, Bewegung fördert den Stoffaustausch."},{"d":"a","r":9,"c":10,"a":"MARKHOEHLE","q":"Welcher Hohlraum im Knochenschaft enthält das Knochenmark?","n":9,"info":"Markhöhle: Hohlraum im Schaft, beim Erwachsenen mit Fettmark gefüllt und innen vom Endost ausgekleidet."},{"d":"a","r":12,"c":12,"a":"MENISKEN","q":"Welche Faserknorpelscheiben gleichen im Knie die Gelenkflächen aus?","n":10,"info":"Menisken: Faserknorpelige Halbmonde im Kniegelenk; vergrößern die Kontaktfläche und verteilen den Druck; der Innenmeniskus ist mit dem Innenband verwachsen."},{"d":"d","r":0,"c":2,"a":"SKELETTMUSKEL","q":"Welche Muskelart ist quergestreift und willkürlich steuerbar?","n":2,"info":"Skelettmuskel: Quergestreift und willkürlich; aus Faszikeln von Muskelfasern, umhüllt von Endo-, Peri- und Epimysium und der Faszie."},{"d":"d","r":2,"c":4,"a":"ENDOMETRIOSE","q":"Chronische, östrogenabhängige Entzündungserkrankung mit gebärmutterschleimhautähnlichem Gewebe außerhalb der …","n":3,"info":"Endometriose: Starke Regelschmerzen, chronischer Unterbauchschmerz, Schmerz bei Geschlechtsverkehr, Stuhlgang oder Wasserlassen, unerfüllter Kinderwunsch"},{"d":"d","r":2,"c":8,"a":"ROSAZEA","q":"Chronisch-entzündliche Gesichtsdermatose mit Gefäßreaktivität und Entzündung, meist ab dem 30. Lebensjahr, häufiger …","n":4,"info":"Rosazea: Anfallsartige Rötung (Flushing), persistierendes Gesichtserythem, Teleangiektasien, Papeln/Pusteln ohne Komedonen; zentrofazial"},{"d":"d","r":2,"c":10,"a":"EPIDIDYMITIS","q":"Entzündung des …: bei jüngeren, sexuell aktiven Männern meist Chlamydien/Gonokokken, bei älteren Männern …","n":5,"info":"Epididymitis (Nebenhodenentzündung): Einseitige, über Stunden bis Tage zunehmende Schwellung und Schmerzen im Hodensack, Fieber, ggf. Dysurie und Ausfluss"},{"d":"d","r":3,"c":0,"a":"GELENKKAPSEL","q":"Welche zweischichtige Hülle umschließt ein echtes Gelenk?","n":6,"info":"Gelenkkapsel: Außen Membrana fibrosa (Stabilität), innen Membrana synovialis (bildet die Synovia); umschließt den Gelenkspalt."},{"d":"d","r":3,"c":6,"a":"KREUZBAENDER","q":"Welche Bänder im Kniegelenk verhindern die Schubladenbewegung?","n":7,"info":"Kreuzbänder: Vorderes und hinteres Kreuzband im Kniegelenk sichern gegen das Verschieben des Unterschenkels nach vorn bzw. hinten."},{"d":"d","r":5,"c":13,"a":"VARIKOZELE","q":"Erweiterung des venösen Plexus pampiniformis am Samenstrang, meist links (die linke V. testicularis mündet …","n":8,"info":"Varikozele (Krampfader im Hodensack): Oft symptomlos; Schweregefühl oder ziehender Schmerz, tastbares 'Wurmkonvolut', Zunahme im Stehen und beim Pressen"}]},{"id":"med-de-36","cat":"med","lang":"de","level":4,"title":"Bewegung, Haut & Fortpflanzung VI","w":20,"h":18,"x":11,"entries":[{"d":"a","r":0,"c":4,"a":"HYDROXYLAPATIT","q":"Welches Mineral macht die Knochenmatrix hart?","n":1,"info":"Hydroxylapatit: Calciumphosphat-Kristalle der Knochenmatrix; verleihen Härte und Druckfestigkeit und speichern rund 99 % des Körpercalciums."},{"d":"a","r":2,"c":3,"a":"KERATINOZYTEN","q":"Welche Zellen machen den Großteil der Epidermis aus?","n":2,"info":"Keratinozyten: Hauptzellen der Epidermis (rund 90 %); wandern von basal nach oben und verhornen dabei."},{"d":"a","r":5,"c":0,"a":"RHABDOMYOLYSE","q":"Zerfall von Skelettmuskelzellen mit Freisetzung von Myoglobin, Kalium und CK ins Blut","n":5,"info":"Rhabdomyolyse: Muskelschmerzen und -schwäche, Schwellung, dunkelbrauner ('colafarbener') Urin; Gefahr des akuten Nierenversagens"},{"d":"a","r":7,"c":3,"a":"OSTEOMALAZIE","q":"Gestörte Mineralisation des Knochens beim Erwachsenen (nach Schluss der Wachstumsfugen), meist durch …","n":7,"info":"Osteomalazie: Diffuse Knochenschmerzen, proximale Muskelschwäche, Watschelgang, Ermüdungsfrakturen"},{"d":"a","r":10,"c":10,"a":"OSTEOBLAST","q":"Welche Zelle bildet neue Knochenmatrix?","n":8,"info":"Osteoblast: Knochenbildende Zelle; sezerniert Osteoid (v. a. Kollagen Typ I) und steuert dessen Mineralisierung (alkalische Phosphatase)."},{"d":"a","r":13,"c":9,"a":"PRIAPISMUS","q":"Schmerzhafte Dauererektion über 4 Stunden ohne sexuelle Erregung; ischämisch (häufigster Typ, Notfall: …","n":9,"info":"Priapismus: Anhaltende, schmerzhafte, harte Erektion der Schwellkörper bei weicher Eichel"},{"d":"d","r":0,"c":4,"a":"HUEFTDYSPLASIE","q":"… Reifungsstörung der Hüftpfanne mit ungenügender Überdachung des Hüftkopfes bis zur Luxation; häufigste …","n":1,"info":"Hüftdysplasie (angeborene Hüftreifungsstörung): Beim Säugling meist unauffällig; Abspreizhemmung, Faltenasymmetrie, Beinlängendifferenz; unbehandelt Hinken und frühe Arthrose"},{"d":"d","r":4,"c":7,"a":"SYNOVIOZYTEN","q":"Welche Zellen der Gelenkinnenhaut bilden Hyaluronsäure?","n":3,"info":"Synoviozyten (Typ A/B): Typ A makrophagenähnlich (Phagozytose), Typ B fibroblastenähnlich (Hyaluronsäure); bei rheumatoider Arthritis wuchern sie zum Pannus."},{"d":"d","r":4,"c":14,"a":"HODENTORSION","q":"Drehung des Hodens um den Samenstrang mit Unterbrechung der Blutversorgung; urologischer Notfall, v. a. bei …","n":4,"info":"Hodentorsion: Plötzlicher, heftiger einseitiger Hodenschmerz (oft aus dem Schlaf), Übelkeit, Erbrechen, Hodenhochstand, fehlender Kremasterreflex"},{"d":"d","r":5,"c":1,"a":"HODENKARZINOM","q":"Häufigster bösartiger solider Tumor junger Männer (etwa 20–40 Jahre), meist … (Seminom oder Nichtseminom)","n":6,"info":"Hodenkarzinom (Keimzelltumor): Schmerzlose, harte, einseitige Hodenvergrößerung oder Knoten, Schweregefühl; selten Gynäkomastie, Rückenschmerz (Lymphknotenmetastasen)"},{"d":"d","r":13,"c":9,"a":"PAGET","q":"Morbus …: Lokalisierte Störung des Knochenumbaus mit überaktiven Osteoklasten und chaotischem Neuaufbau → verdickter, aber …","n":9,"info":"Morbus Paget (Ostitis deformans): Häufig asymptomatisch (Zufallsbefund); Knochenschmerz, Verformung (Säbelscheidentibia), zunehmender Kopfumfang, Schwerhörigkeit"}]},{"id":"med-de-37","cat":"med","lang":"de","level":4,"title":"Bewegung, Haut & Fortpflanzung VII","w":21,"h":14,"x":11,"entries":[{"d":"a","r":1,"c":3,"a":"PRAEEKLAMPSIE","q":"Schwangerschaftsspezifische Multisystemerkrankung ab der 20. SSW: neu aufgetretene Hypertonie plus Proteinurie oder …","n":2,"info":"Präeklampsie (inkl. HELLP-Syndrom): Bluthochdruck, Ödeme, Kopfschmerz, Augenflimmern, rechtsseitiger Oberbauchschmerz, Hyperreflexie; schwer: Krampfanfälle (Eklampsie)"},{"d":"a","r":4,"c":0,"a":"CHONDROZYTEN","q":"Welche Zellen bilden die Matrix des Gelenkknorpels?","n":5,"info":"Chondrozyten: Knorpelzellen in Lakunen, oft in isogenen Gruppen; bilden Kollagen Typ II und Proteoglykane, regenerieren aber kaum."},{"d":"a","r":4,"c":13,"a":"OSTEOZYT","q":"Welche Zellen sitzen in Lakunen der Knochenmatrix und registrieren Belastung?","n":6,"info":"Osteozyt: Eingemauerter ehemaliger Osteoblast in einer Lakune; über Fortsätze vernetzt, misst er Belastung und steuert den Umbau (z. B. über Sklerostin)."},{"d":"a","r":7,"c":3,"a":"MYOMETRIUM","q":"Welche Uterusschicht kontrahiert unter Oxytocin bei der Geburt?","n":8,"info":"Myometrium: Dicke glatte Muskelschicht des Uterus; Oxytocin löst Wehen aus, in der Schwangerschaft starke Hypertrophie."},{"d":"a","r":9,"c":3,"a":"TYPIIFASERN","q":"Welche Muskelfasern sind schnell und kraftvoll, aber rasch ermüdbar?","n":9,"info":"Typ-II-Fasern: Schnelle, helle, überwiegend glykolytische Fasern; große Kraft, aber rasch ermüdbar; nehmen im Alter besonders ab."},{"d":"a","r":11,"c":5,"a":"LEYDIGZELLEN","q":"Welche Zellen bilden unter LH Testosteron?","n":10,"info":"Leydig-Zellen: Liegen im Interstitium zwischen den Kanälchen und bilden unter LH Testosteron."},{"d":"a","r":13,"c":10,"a":"MASERN","q":"Hoch ansteckende, aerogen übertragene Virusinfektion mit Fieber, Katarrh und Exanthem; hinterlässt eine …","n":11,"info":"Masern (Morbilli): Hohes Fieber, Schnupfen, Husten, Konjunktivitis, Koplik-Flecken der Wangenschleimhaut, dann makulopapulöses Exanthem vom Kopf absteigend"},{"d":"d","r":0,"c":5,"a":"FASERKNORPEL","q":"Welcher Knorpeltyp bildet Bandscheiben, Menisken und Symphyse?","n":1,"info":"Faserknorpel: Knorpel mit vielen Kollagen-Typ-I-Fasern, sehr zugfest – in Bandscheiben, Menisken und Symphyse."},{"d":"d","r":2,"c":0,"a":"RACHITIS","q":"Mineralisationsstörung des wachsenden Skeletts bei Kindern, meist durch Vitamin-D- oder Calciummangel; betrifft …","n":3,"info":"Rachitis: Verzögerter Fontanellenschluss, Kraniotabes, rachitischer Rosenkranz, Beinfehlstellungen (O-Beine), Muskelhypotonie"},{"d":"d","r":3,"c":3,"a":"ENDOMETRIUM","q":"Welche Schleimhautschicht wird bei der Menstruation teilweise abgestoßen?","n":4,"info":"Endometrium: Gebärmutterschleimhaut: Die Funktionalis wird zyklisch auf- und abgebaut (Menstruation), die Basalis regeneriert sie."},{"d":"d","r":4,"c":15,"a":"TYPIFASERN","q":"Welche Muskelfasern sind ermüdungsresistent und reich an Myoglobin?","n":7,"info":"Typ-I-Fasern: Langsame, rote, oxidative Fasern mit vielen Mitochondrien und viel Myoglobin; ermüdungsresistent, für Haltung und Ausdauer."}]},{"id":"med-de-38","cat":"med","lang":"de","level":4,"title":"Bewegung, Haut & Fortpflanzung VIII","w":18,"h":18,"x":11,"entries":[{"d":"a","r":0,"c":6,"a":"SPERMIUM","q":"Welche Zelle besitzt Akrosom, Mittelstück und Geißel?","n":1,"info":"Spermium: Kopf mit Kern und Akrosom (Enzyme zum Eindringen in die Eizelle), Mittelstück mit Mitochondrien, Geißel zur Fortbewegung."},{"d":"a","r":2,"c":5,"a":"SERTOLIZELLEN","q":"Welche Zellen bilden die Blut-Hoden-Schranke?","n":3,"info":"Sertoli-Zellen: Stützzellen des Keimepithels; bilden mit Tight Junctions die Blut-Hoden-Schranke und unter FSH Inhibin und ABP."},{"d":"a","r":4,"c":2,"a":"HODENHOCHSTAND","q":"Ein oder beide Hoden liegen nicht dauerhaft im Hodensack, sondern im Leistenkanal oder Bauchraum; häufig bei …","n":5,"info":"Hodenhochstand (Maldescensus testis, Kryptorchismus): Leere Hodensackhälfte auf einer oder beiden Seiten, Hoden ggf. in der Leiste tastbar"},{"d":"a","r":9,"c":0,"a":"MELANOZYTEN","q":"Welche Zellen bilden das Hautpigment?","n":10,"info":"Melanozyten: Aus der Neuralleiste stammende Zellen im Stratum basale; geben Melanin über Fortsätze an Keratinozyten ab (UV-Schutz)."},{"d":"d","r":0,"c":7,"a":"PERTHES","q":"Morbus …: Idiopathische avaskuläre Nekrose des Hüftkopfes im Kindesalter, meist bei Jungen im Vor- und Grundschulalter; heilt …","n":2,"info":"Morbus Perthes (Legg-Calvé-Perthes): Hinken, Hüft- oder Knieschmerz (oft ins Knie projiziert), eingeschränkte Abduktion und Innenrotation"},{"d":"d","r":2,"c":5,"a":"SPERMATOGONIEN","q":"Welche Stammzellen des Keimepithels liegen der Basalmembran an?","n":3,"info":"Spermatogonien: Diploide Stammzellen an der Basalmembran; teilen sich mitotisch und treten als Spermatozyten in die Meiose ein."},{"d":"d","r":4,"c":0,"a":"SARKOMER","q":"Welche kleinste kontraktile Einheit liegt zwischen zwei Z-Scheiben?","n":4,"info":"Sarkomer: Kleinste kontraktile Einheit zwischen zwei Z-Scheiben; bei Kontraktion verkürzen sich I-Bande und H-Zone, die A-Bande bleibt gleich lang."},{"d":"d","r":4,"c":3,"a":"OVARIALTORSION","q":"Stieldrehung des Eierstocks (oft mit Eileiter) um sein Gefäßband mit Unterbrechung der Durchblutung; meist bei …","n":6,"info":"Ovarialtorsion (Adnextorsion): Plötzlicher, heftiger einseitiger Unterbauchschmerz, oft mit Übelkeit und Erbrechen, teils nach Sport oder Bewegung"},{"d":"d","r":4,"c":12,"a":"TTUBULI","q":"Welche Membraneinstülpungen leiten das Aktionspotenzial ins Faserinnere?","n":7,"info":"T-Tubuli: Einstülpungen der Zellmembran, die das Aktionspotenzial tief in die Faser leiten; der Dihydropyridinrezeptor dient dort als Spannungssensor."},{"d":"d","r":7,"c":8,"a":"VITILIGO","q":"Erworbene Autoimmunerkrankung, bei der zytotoxische T-Zellen Melanozyten zerstören → scharf begrenzte, pigmentfreie …","n":8,"info":"Vitiligo (Weißfleckenkrankheit): Milchweiße, scharf begrenzte, nicht schuppende Flecken, oft symmetrisch an Gesicht, Händen und um Körperöffnungen"},{"d":"d","r":7,"c":10,"a":"SYNOVIA","q":"Welche Flüssigkeit schmiert das Gelenk und ernährt den Knorpel?","n":9,"info":"Synovia (Gelenkflüssigkeit): Viskose Flüssigkeit mit Hyaluronsäure und Lubricin; schmiert das Gelenk und ernährt den Knorpel."}]},{"id":"med-de-39","cat":"med","lang":"de","level":4,"title":"Bewegung, Haut & Fortpflanzung IX","w":18,"h":18,"x":11,"entries":[{"d":"a","r":0,"c":0,"a":"ACHONDROPLASIE","q":"Häufigste Form des genetisch bedingten dysproportionierten Kleinwuchses: aktivierende FGFR3-Mutation …","n":1,"info":"Achondroplasie: Kurze Extremitäten (v. a. rhizomel), normal langer Rumpf, großer Kopf mit vorgewölbter Stirn, Dreizackhand, normale Intelligenz"},{"d":"a","r":3,"c":0,"a":"STRESSFRAKTUR","q":"Knochenbruch durch wiederholte, unterschwellige Überlastung ohne adäquates Trauma (z. B. Läufer, Rekruten: …","n":5,"info":"Stressfraktur (Ermüdungsfraktur): Zunehmender, belastungsabhängiger, punktueller Knochenschmerz, später auch in Ruhe; lokale Schwellung und Druckschmerz"},{"d":"a","r":5,"c":5,"a":"MUSKELSPINDEL","q":"Welcher Rezeptor im Muskel misst die Dehnung und startet den Eigenreflex?","n":6,"info":"Muskelspindel: Dehnungsrezeptor zwischen den Arbeitsfasern; meldet über Ia-Fasern die Muskellänge und löst den Dehnungsreflex aus."},{"d":"a","r":8,"c":5,"a":"OSTEOCHONDROM","q":"Häufigster gutartiger Knochentumor: knöcherner Auswuchs mit Knorpelkappe, meist metaphysennah an langen …","n":7,"info":"Osteochondrom (kartilaginäre Exostose): Schmerzlose, harte Vorwölbung am Knochen, ggf. Beschwerden durch Druck auf Sehnen, Nerven oder Gefäße"},{"d":"a","r":13,"c":7,"a":"EWINGSARKOM","q":"Hochmaligner Knochentumor aus kleinen, runden, blauen Zellen bei Kindern und Jugendlichen; typisch Diaphyse langer …","n":9,"info":"Ewing-Sarkom: Schmerz und Schwellung, oft mit Fieber, erhöhter BSG und Leukozytose (kann eine Osteomyelitis vortäuschen)"},{"d":"d","r":0,"c":3,"a":"OSTEOMYELITIS","q":"Infektion von Knochen und Knochenmark: hämatogen (v. a. Kinder","n":2,"info":"Osteomyelitis: Lokaler Knochenschmerz, Schwellung, Rötung, Fieber; chronisch: Fistelbildung"},{"d":"d","r":1,"c":16,"a":"BLASENMOLE","q":"Gestationsbedingte Trophoblasterkrankung nach abnormer Befruchtung: komplette Mole (nur väterliche Chromosomen, kein …","n":3,"info":"Blasenmole (Molenschwangerschaft): Vaginale Blutung im 1. Trimenon, für die SSW zu großer Uterus, ausgeprägte Übelkeit/Hyperemesis, ggf. Hyperthyreose, frühe Präeklampsie"},{"d":"d","r":2,"c":7,"a":"PROSTATAZONEN","q":"In welche Bereiche wird die Vorsteherdrüse nach McNeal eingeteilt?","n":4,"info":"Prostatazonen: Periphere Zone (ca. 70 %, Ursprung der meisten Karzinome), Transitionszone (benigne Hyperplasie) und zentrale Zone."},{"d":"d","r":3,"c":0,"a":"SCHEUERMANN","q":"Morbus …: Wachstumsstörung der Wirbelkörper-Grund- und Deckplatten im Jugendalter mit keilförmigen Wirbeln und vermehrter, …","n":5,"info":"Morbus Scheuermann (Adoleszentenkyphose): Rundrücken, der sich nicht aktiv aufrichten lässt, Rückenschmerz nach Belastung; oft schmerzarm"},{"d":"d","r":8,"c":5,"a":"OSTEOKLAST","q":"Welche mehrkernige Zelle baut Knochen ab?","n":7,"info":"Osteoklast: Mehrkernige Riesenzelle aus der Monozytenlinie; baut Knochen in Howship-Lakunen mit Säure und Enzymen ab, aktiviert über RANKL."},{"d":"d","r":12,"c":12,"a":"OSTEON","q":"Welche zylindrische Baueinheit der Kompakta besteht aus Lamellen um einen Zentralkanal?","n":8,"info":"Osteon (Havers-System): Baueinheit der Kompakta: konzentrische Lamellen um einen zentralen Havers-Kanal mit Gefäß; quer verbinden Volkmann-Kanäle."}]}];
